pub mod store;
pub mod extract;
pub mod ai_semantic;
pub mod formal;

pub use graph::{NodeKind, EdgeKind, SpecGraph, SpecNodeData, SpecEdgeData};
pub use graph::{Contradiction, Omission, LayerInconsistency, InterUniverseInconsistency, TestCoverage, ComplianceScore};
pub use graph::{TemporalSnapshot, TemporalDiff, NodeHistory, HistoryEvent, ComplianceTrend, ComplianceDataPoint};
pub use store::{FileStore, DirectoryStore, Store};
pub use extract::{RustExtractor, ProtoExtractor, DocExtractor, ArchitectureExtractor, PHPTestExtractor, InferredSpecification, IngestionReport, EdgeSuggestion};
pub use ai_semantic::AISemantic;
// Re-export from formal module
pub use formal::{UDAFModel, Universe, Domain, AdmissibleSet, TransformFunction, TransformStrategy, Constraint, ConstraintKind, TransformKind};
pub use formal::{UniverseId, DomainId, SpecId, TransformId, IdError};
pub use formal::{MetadataKey, Metadata, UniverseMetadata, DomainMetadata, ConstraintMetadata, TransformMetadata};
pub use formal::{SpecSet, DomainSet};
pub use formal::{Proof, Property, ProofMethod, ProofStatus, ProofStep};
#[cfg(feature = "z3-solver")]
pub use formal::{Prover, UnderspecificationReport};

use chrono::Utc;
use petgraph::graph::{DiGraph, EdgeIndex, NodeIndex};
use petgraph::visit::EdgeRef;
use petgraph::Direction;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use uuid::Uuid;

// Import formal verification modules
use crate::formal::{AdmissibleSet, Constraint, ConstraintKind};
#[cfg(feature = "z3-solver")]
use crate::formal::{Prover, ProofStatus};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum NodeKind {
    Assertion,
    Constraint,
    Scenario,
    Definition,
    Domain,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EdgeKind {
    Refines,
    DependsOn,
    Contradicts,
    DerivesFrom,
    Synonym,
    Composes,
    Formalizes,  // Target is a more formal version of source
    Transform,   // Function f: maps spec from source universe to target universe
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SpecNodeData {
    pub id: String,
    pub content: String,
    pub kind: NodeKind,
    pub metadata: HashMap<String, String>,
    #[serde(default)]
    pub created_at: i64,
    #[serde(default)]
    pub modified_at: i64,
    #[serde(default)]
    pub formality_layer: u8,  // 0=natural, 1=structured, 2=formal, 3=executable
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpecEdgeData {
    pub id: String,
    pub kind: EdgeKind,
    pub metadata: HashMap<String, String>,
    #[serde(default)]
    pub created_at: i64,
}

/// Edge with source/target node IDs (for serialization)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Edge {
    pub source: String,
    pub target: String,
    #[serde(flatten)]
    pub data: SpecEdgeData,
}

#[derive(Debug, Clone)]
pub struct Contradiction {
    pub node_a: SpecNodeData,
    pub node_b: SpecNodeData,
    pub explanation: String,
}

#[derive(Debug, Clone)]
pub struct Omission {
    pub description: String,
    pub related_nodes: Vec<SpecNodeData>,
}

#[derive(Debug, Clone)]
pub struct LayerInconsistency {
    pub source: SpecNodeData,
    pub target: SpecNodeData,
    pub explanation: String,
}

#[derive(Debug, Clone)]
pub struct InterUniverseInconsistency {
    pub universe_a: String,  // Universe identifier (from metadata)
    pub universe_b: String,
    pub spec_a: SpecNodeData,
    pub spec_b: SpecNodeData,
    pub transform_path: Vec<String>,  // Edge IDs forming the transformation path
    pub explanation: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpecGraph {
    graph: DiGraph<SpecNodeData, SpecEdgeData>,
