fn calculate_compliance_constraint_high_match() {
    let mut g = SpecGraph::new();
    let constraint_id = g
        .add_node("Response time must be less than 100ms".into(), NodeKind::Constraint, HashMap::new())
        .id
        .clone();

    let code = r#"
