   338→    pub fn detect_contradictions(&self) -> Vec<Contradiction> {
   339→        let mut result = Vec::new();
   340→
   341→        // Explicit contradiction edges
   342→        for eidx in self.graph.edge_indices() {
   343→            let edge = &self.graph[eidx];
   344→            if edge.kind == EdgeKind::Contradicts {
   345→                if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
