   347→                        node_a: self.graph[src_idx].clone(),
   348→                        node_b: self.graph[tgt_idx].clone(),
   349→                        explanation: format!(
   350→                            "Explicit contradiction edge '{}'",
   351→                            edge.id
   352→                        ),
   353→                    });
   354→                }
   355→            }
   356→        }
   357→
   358→        // Structural: nodes in the same domain with conflicting kinds
   359→        // (Constraint + Scenario on same domain may indicate tension)
   360→        let domains: Vec<(NodeIndex, &SpecNodeData)> = self
   361→            .graph
   362→            .node_indices()
   363→            .map(|idx| (idx, &self.graph[idx]))
   364→            .filter(|(_, n)| n.kind == NodeKind::Domain)
   365→            .collect();
   366→
   367→        for (domain_idx, _domain_data) in &domains {
   368→            let children: Vec<(NodeIndex, &SpecNodeData)> = self
   369→                .graph
   370→                .edges_directed(*domain_idx, Direction::Incoming)
   371→                .filter_map(|e| {
   372→                    if self.graph[e.id()].kind == EdgeKind::Refines
   373→                        || self.graph[e.id()].kind == EdgeKind::DependsOn
   374→                    {
   375→                        let src = e.source();
   376→                        Some((src, &self.graph[src]))
   377→                    } else {
   378→                        None
   379→                    }
   380→                })
   381→                .collect();
   382→
   383→            let constraints: Vec<&SpecNodeData> = children
   384→                .iter()
   385→                .filter(|(_, n)| n.kind == NodeKind::Constraint)
   386→                .map(|(_, n)| *n)
   387→                .collect();
   388→            let scenarios: Vec<&SpecNodeData> = children
   389→                .iter()
   390→                .filter(|(_, n)| n.kind == NodeKind::Scenario)
   391→                .map(|(_, n)| *n)
   392→                .collect();
   393→
   394→            // Flag when constraints and scenarios coexist under the same domain —
   395→            // this is a potential tension point that warrants review.
   396→            if !constraints.is_empty() && !scenarios.is_empty() {
   397→                for c in &constraints {
   398→                    for s in &scenarios {
   399→                        result.push(Contradiction {
   400→                            node_a: (*c).clone(),
   401→                            node_b: (*s).clone(),
   402→                            explanation: format!(
   403→                                "Potential tension: constraint and scenario under same domain"
   404→                            ),
   405→                        });
   406→                    }
   407→                }
   408→            }
   409→        }
   410→
   411→        // Detect duplicates and semantic contradictions within same layer
   412→        let all_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
   413→            .graph
   414→            .node_indices()
   415→            .map(|idx| (idx, &self.graph[idx]))
   416→            .filter(|(_, node)| {
   417→                // Skip Definitions (meta-specifications, examples, test data)
   418→                node.kind != NodeKind::Definition
   419→            })
   420→            .collect();
   421→
   422→        for i in 0..all_nodes.len() {
   423→            for j in (i + 1)..all_nodes.len() {
   424→                let (idx_a, node_a) = all_nodes[i];
   425→                let (idx_b, node_b) = all_nodes[j];
   426→
   427→                // Skip if nodes are connected by Synonym edge (duplicates are intentional)
   428→                let has_synonym_edge = self.graph.edges_connecting(idx_a, idx_b).any(|e| {
   429→                    self.graph[e.id()].kind == EdgeKind::Synonym
   430→                }) || self.graph.edges_connecting(idx_b, idx_a).any(|e| {
   431→                    self.graph[e.id()].kind == EdgeKind::Synonym
   432→                });
   433→                if has_synonym_edge {
   434→                    continue;
   435→                }
   436→
   437→                // Check for exact duplicates (same content and kind)
   438→                if node_a.content.trim() == node_b.content.trim() && node_a.kind == node_b.kind {
   439→                    result.push(Contradiction {
   440→                        node_a: node_a.clone(),
   441→                        node_b: node_b.clone(),
   442→                        explanation: format!(
   443→                            "Duplicate specification: same content and kind '{:?}'",
   444→                            node_a.kind
   445→                        ),
   446→                    });
   447→                    continue; // Skip semantic check if exact duplicate
   448→                }
   449→
   450→                // Check for semantic contradictions (e.g., password 8 vs 10 chars)
   451→                // Only check within same formality layer to avoid false positives
   452→                if node_a.formality_layer == node_b.formality_layer {
   453→                    // Try Z3 formal verification first (provides mathematical certainty)
   454→                    if let Some(explanation) = Self::detect_contradiction_via_z3(node_a, node_b) {
   455→                        result.push(Contradiction {
   456→                            node_a: node_a.clone(),
   457→                            node_b: node_b.clone(),
   458→                            explanation,
   459→                        });
   460→                        continue; // Z3 proof is conclusive, skip heuristic check
   461→                    }
   462→
   463→                    // Fallback to heuristic keyword matching if Z3 can't extract constraints
   464→                    if let Some(explanation) = Self::detect_semantic_contradiction(
   465→                        &node_a.content,
   466→                        &node_b.content,
   467→                    ) {
   468→                        result.push(Contradiction {
   469→                            node_a: node_a.clone(),
   470→                            node_b: node_b.clone(),
   471→                            explanation,
   472→                        });
   473→                    }
   474→                }
   475→            }
   476→        }
   477→
   478→        result
   479→    }
