   554→    /// Find all synonym groups: nodes connected by Synonym edges.
   555→    pub fn resolve_term(&self, term: &str) -> (Vec<&SpecNodeData>, Vec<String>) {
   556→        let t = term.to_lowercase();
   557→
   558→        // Find definition nodes matching the term
   559→        let definitions: Vec<&SpecNodeData> = self
   560→            .graph
   561→            .node_weights()
   562→            .filter(|n| n.kind == NodeKind::Definition && n.content.to_lowercase().contains(&t))
   563→            .collect();
   564→
   565→        // Collect synonyms via Synonym edges
   566→        let mut synonyms = Vec::new();
   567→        for def in &definitions {
   568→            if let Some(&idx) = self.id_to_index.get(&def.id) {
   569→                for edge in self
   570→                    .graph
   571→                    .edges_directed(idx, Direction::Outgoing)
   572→                    .chain(self.graph.edges_directed(idx, Direction::Incoming))
   573→                {
   574→                    if self.graph[edge.id()].kind == EdgeKind::Synonym {
   575→                        let other_idx = if edge.source() == idx {
   576→                            edge.target()
   577→                        } else {
   578→                            edge.source()
   579→                        };
   580→                        let other = &self.graph[other_idx];
   581→                        if !synonyms.contains(&other.content) {
   582→                            synonyms.push(other.content.clone());
   583→                        }
   584→                    }
   585→                }
   586→            }
   587→        }
   588→
   589→        (definitions, synonyms)
   590→    }
