   630→    /// Detect inter-universe inconsistencies: specifications across different universes
   631→    /// (U₁, U₂, ...) that contradict each other despite Transform edges connecting them.
   632→    /// This addresses the conversation.md critique about multi-layered specifications.
   633→    pub fn detect_inter_universe_inconsistencies(&self) -> Vec<InterUniverseInconsistency> {
   634→        let mut result = Vec::new();
   635→
   636→        // Group nodes by universe (from metadata "universe" field)
   637→        let mut universe_nodes: HashMap<String, Vec<(NodeIndex, &SpecNodeData)>> = HashMap::new();
   638→        for idx in self.graph.node_indices() {
   639→            let node = &self.graph[idx];
   640→            if let Some(universe) = node.metadata.get("universe") {
   641→                universe_nodes
   642→                    .entry(universe.clone())
   643→                    .or_insert_with(Vec::new)
   644→                    .push((idx, node));
   645→            }
   646→        }
   647→
   648→        // For each Transform edge, check if the specifications are consistent
   649→        for eidx in self.graph.edge_indices() {
   650→            let edge = &self.graph[eidx];
   651→            if edge.kind == EdgeKind::Transform {
   652→                if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
   653→                    let src_node = &self.graph[src_idx];
   654→                    let tgt_node = &self.graph[tgt_idx];
   655→
   656→                    let src_universe = src_node.metadata.get("universe").map(|s| s.as_str());
   657→                    let tgt_universe = tgt_node.metadata.get("universe").map(|s| s.as_str());
   658→
   659→                    // Only check if both nodes have universe metadata and they differ
   660→                    if let (Some(u_a), Some(u_b)) = (src_universe, tgt_universe) {
   661→                        if u_a != u_b {
   662→                            // Check for semantic contradiction via simple heuristics:
   663→                            // 1. Contradictory keywords (must/must not, required/forbidden)
   664→                            // 2. Conflicting numeric constraints
   665→                            let contradiction = Self::detect_semantic_contradiction(
   666→                                &src_node.content,
   667→                                &tgt_node.content,
   668→                            );
   669→
   670→                            if let Some(explanation) = contradiction {
   671→                                result.push(InterUniverseInconsistency {
   672→                                    universe_a: u_a.to_string(),
   673→                                    universe_b: u_b.to_string(),
   674→                                    spec_a: src_node.clone(),
   675→                                    spec_b: tgt_node.clone(),
   676→                                    transform_path: vec![edge.id.clone()],
   677→                                    explanation,
   678→                                });
   679→                            }
   680→                        }
   681→                    }
   682→                }
   683→            }
   684→        }
   685→
   686→        // Check for contradictions across universes without direct Transform edges
   687→        // (this catches missing transformation functions - the "f" gap)
   688→        let universe_names: Vec<String> = universe_nodes.keys().cloned().collect();
   689→        for i in 0..universe_names.len() {
   690→            for j in (i + 1)..universe_names.len() {
   691→                let u_a = &universe_names[i];
   692→                let u_b = &universe_names[j];
   693→
   694→                if let (Some(nodes_a), Some(nodes_b)) =
   695→                    (universe_nodes.get(u_a), universe_nodes.get(u_b))
   696→                {
   697→                    // Check if there's a Transform path between these universes
   698→                    let has_transform = self.graph.edge_indices().any(|eidx| {
   699→                        let edge = &self.graph[eidx];
   700→                        if edge.kind != EdgeKind::Transform {
   701→                            return false;
   702→                        }
   703→                        if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
   704→                            let src_u = self.graph[src_idx].metadata.get("universe");
   705→                            let tgt_u = self.graph[tgt_idx].metadata.get("universe");
   706→                            (src_u.map(|s| s.as_str()) == Some(u_a.as_str())
   707→                                && tgt_u.map(|s| s.as_str()) == Some(u_b.as_str()))
   708→                                || (src_u.map(|s| s.as_str()) == Some(u_b.as_str())
   709→                                    && tgt_u.map(|s| s.as_str()) == Some(u_a.as_str()))
   710→                        } else {
   711→                            false
   712→                        }
   713→                    });
   714→
   715→                    // If no transform exists but both universes have related concepts, flag it
   716→                    if !has_transform {
   717→                        for (_, node_a) in nodes_a {
   718→                            for (_, node_b) in nodes_b {
   719→                                // Check if concepts are related (similar content)
   720→                                if Self::are_related_concepts(&node_a.content, &node_b.content) {
   721→                                    result.push(InterUniverseInconsistency {
   722→                                        universe_a: u_a.clone(),
   723→                                        universe_b: u_b.clone(),
   724→                                        spec_a: (*node_a).clone(),
   725→                                        spec_b: (*node_b).clone(),
   726→                                        transform_path: vec![],
   727→                                        explanation: format!(
   728→                                            "Missing transformation function (f) between universes '{}' and '{}' for related concepts",
   729→                                            u_a, u_b
   730→                                        ),
   731→                                    });
   732→                                }
   733→                            }
   734→                        }
   735→                    }
   736→                }
   737→            }
   738→        }
   739→
   740→        result
   741→    }
