   743→    /// Helper: detect semantic contradiction between two specification strings
   744→    fn detect_semantic_contradiction(content_a: &str, content_b: &str) -> Option<String> {
   745→        let a_lower = content_a.to_lowercase();
   746→        let b_lower = content_b.to_lowercase();
   747→
   748→        // Check for must/must not conflicts (only if concepts are related)
   749→        // Exclude specs that have both "must" and "must not" within the same text
   750→        // (e.g., "must maintain idempotency: ... must not create duplicates" - not contradictory)
   751→        let a_has_must = a_lower.contains("must") && !a_lower.contains("must not");
   752→        let b_has_must_not = b_lower.contains("must not") || b_lower.contains("forbidden");
   753→        let a_has_both = a_lower.contains("must") && a_lower.contains("must not");
   754→        let b_has_both = b_lower.contains("must") && b_lower.contains("must not");
   755→
   756→        if a_has_must
   757→            && b_has_must_not
   758→            && !a_has_both  // Exclude if A has both "must" and "must not"
   759→            && !b_has_both  // Exclude if B has both "must" and "must not"
   760→            && Self::are_related_concepts(content_a, content_b)
   761→        {
   762→            return Some("Contradictory requirement: 'must' vs 'must not'".to_string());
   763→        }
   764→
   765→        // Check for required/optional conflicts (only if concepts are related)
   766→        if a_lower.contains("required") && b_lower.contains("optional")
   767→            && Self::are_related_concepts(content_a, content_b)
   768→        {
   769→            return Some("Contradictory requirement: 'required' vs 'optional'".to_string());
   770→        }
   771→
   772→        // Extract and compare numeric constraints
   773→        if let (Some(num_a), Some(num_b)) = (Self::extract_minimum_value(&a_lower), Self::extract_minimum_value(&b_lower)) {
   774→            if num_a != num_b && a_lower.contains("password") && b_lower.contains("password") {
   775→                return Some(format!("Conflicting password length: {} vs {} characters", num_a, num_b));
   776→            }
   777→            if num_a != num_b && Self::are_related_concepts(content_a, content_b)
   778→                && (a_lower.contains("length") || b_lower.contains("length")
   779→                || a_lower.contains("minimum") || b_lower.contains("minimum")
   780→                || a_lower.contains("at least") || b_lower.contains("at least")) {
   781→                return Some(format!("Conflicting minimum values: {} vs {}", num_a, num_b));
   782→            }
   783→        }
   784→
   785→        // Check for conflicting numeric constraints (only if about same variable)
   786→        if a_lower.contains(">=") && b_lower.contains("<")
   787→            && Self::are_related_concepts(content_a, content_b)
   788→        {
   789→            return Some("Potentially conflicting numeric constraints".to_string());
   790→        }
   791→
   792→        None
   793→    }
