   795→    /// Extract minimum value from phrases like "at least 8", "minimum 10", ">= 5", etc.
   796→    fn extract_minimum_value(text: &str) -> Option<u32> {
   797→        // Try to find patterns like "at least N", "minimum N", ">= N", "min N", "minimum of N"
   798→        use regex::Regex;
   799→        let patterns = [
   800→            r"at least (\d+)",
   801→            r"minimum (\d+)",
   802→            r"min (\d+)",
   803→            r"minimum of (\d+)",
   804→            r">= ?(\d+)",
   805→            r"≥ ?(\d+)",
   806→        ];
   807→
   808→        for pattern in &patterns {
   809→            if let Ok(re) = Regex::new(pattern) {
   810→                if let Some(cap) = re.captures(text) {
   811→                    if let Some(num_str) = cap.get(1) {
   812→                        if let Ok(num) = num_str.as_str().parse::<u32>() {
   813→                            return Some(num);
   814→                        }
   815→                    }
   816→                }
   817→            }
   818→        }
   819→
   820→        None
   821→    }
