   851→    /// Helper: check if two concepts are related (share significant terms or word stems)
   852→    fn are_related_concepts(content_a: &str, content_b: &str) -> bool {
   853→        let a_lower = content_a.to_lowercase();
   854→        let b_lower = content_b.to_lowercase();
   855→
   856→        // Filter out meta-words that don't indicate semantic relatedness
   857→        let meta_words = ["invariant", "template", "contains", "fetched", "expected"];
   858→
   859→        let a_words: Vec<&str> = a_lower
   860→            .split(|c: char| !c.is_alphanumeric())
   861→            .filter(|w| w.len() > 4 && !meta_words.contains(w)) // Only significant words, exclude meta-words
   862→            .collect();
   863→        let b_words: Vec<&str> = b_lower
   864→            .split(|c: char| !c.is_alphanumeric())
   865→            .filter(|w| w.len() > 4 && !meta_words.contains(w))
   866→            .collect();
   867→
   868→        // Check for exact word matches
   869→        let exact_matches = a_words.iter().filter(|w| b_words.contains(w)).count();
   870→        if exact_matches >= 2 {
   871→            return true;
   872→        }
   873→
   874→        // Check for word stems (common prefix of at least 5 chars)
   875→        let mut stem_matches = 0;
   876→        for &word_a in &a_words {
   877→            for &word_b in &b_words {
   878→                let min_len = word_a.len().min(word_b.len());
   879→                if min_len >= 5 {
   880→                    let prefix_len = word_a
   881→                        .chars()
   882→                        .zip(word_b.chars())
   883→                        .take_while(|(a, b)| a == b)
   884→                        .count();
   885→                    if prefix_len >= 5 {
   886→                        stem_matches += 1;
   887→                        break; // Count each word_a only once
   888→                    }
   889→                }
   890→            }
   891→        }
   892→
   893→        exact_matches >= 1 || stem_matches >= 1
   894→    }
