  1131→    /// Trace all relationships for a node, returning a hierarchical structure.
  1132→    /// Returns tuples of (node, edge_kind, direction) where direction is "outgoing" or "incoming".
  1133→    pub fn trace_relationships(&self, node_id: &str, max_depth: usize) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
  1134→        let mut result = Vec::new();
  1135→        let mut visited = std::collections::HashSet::new();
  1136→
  1137→        if let Some(&start_idx) = self.id_to_index.get(node_id) {
  1138→            visited.insert(start_idx);
  1139→            self.trace_recursive(start_idx, max_depth, 0, &mut visited, &mut result);
  1140→        }
  1141→
  1142→        result
  1143→    }
  1144→
  1145→    fn trace_recursive(
  1146→        &self,
  1147→        idx: NodeIndex,
  1148→        max_depth: usize,
  1149→        current_depth: usize,
  1150→        visited: &mut std::collections::HashSet<NodeIndex>,
  1151→        result: &mut Vec<(SpecNodeData, EdgeKind, String, usize)>,
  1152→    ) {
  1153→        if max_depth > 0 && current_depth >= max_depth {
  1154→            return;
  1155→        }
  1156→
  1157→        // Traverse outgoing edges
  1158→        for edge in self.graph.edges_directed(idx, Direction::Outgoing) {
  1159→            let target_idx = edge.target();
  1160→            let edge_data = &self.graph[edge.id()];
  1161→            let target_node = &self.graph[target_idx];
  1162→
  1163→            result.push((
  1164→                target_node.clone(),
  1165→                edge_data.kind,
  1166→                "outgoing".to_string(),
  1167→                current_depth + 1,
  1168→            ));
  1169→
  1170→            if !visited.contains(&target_idx) {
  1171→                visited.insert(target_idx);
  1172→                self.trace_recursive(target_idx, max_depth, current_depth + 1, visited, result);
  1173→            }
  1174→        }
  1175→
  1176→        // Traverse incoming edges
  1177→        for edge in self.graph.edges_directed(idx, Direction::Incoming) {
  1178→            let source_idx = edge.source();
  1179→            let edge_data = &self.graph[edge.id()];
  1180→            let source_node = &self.graph[source_idx];
  1181→
  1182→            result.push((
  1183→                source_node.clone(),
  1184→                edge_data.kind,
  1185→                "incoming".to_string(),
  1186→                current_depth + 1,
  1187→            ));
  1188→
  1189→            if !visited.contains(&source_idx) {
  1190→                visited.insert(source_idx);
  1191→                self.trace_recursive(source_idx, max_depth, current_depth + 1, visited, result);
  1192→            }
  1193→        }
  1194→    }
