  1196→    /// Find potentially related terms based on co-occurrence in metadata or content.
  1197→    /// This provides a lightweight semantic clustering without requiring external AI.
  1198→    pub fn find_related_terms(&self, term: &str) -> Vec<(&SpecNodeData, f32)> {
  1199→        let t = term.to_lowercase();
  1200→        let mut scored_nodes: Vec<(&SpecNodeData, f32)> = Vec::new();
  1201→
  1202→        // Find nodes that mention the term
  1203→        let mentioning_nodes: Vec<&SpecNodeData> = self
  1204→            .graph
  1205→            .node_weights()
  1206→            .filter(|n| n.content.to_lowercase().contains(&t))
  1207→            .collect();
  1208→
  1209→        if mentioning_nodes.is_empty() {
  1210→            return scored_nodes;
  1211→        }
  1212→
  1213→        // Extract significant words from mentioning nodes (excluding common words)
  1214→        let stop_words = ["the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for"];
  1215→        let mut term_context: std::collections::HashSet<String> = std::collections::HashSet::new();
  1216→
  1217→        for node in &mentioning_nodes {
  1218→            for word in node.content.to_lowercase().split_whitespace() {
  1219→                let clean_word = word.trim_matches(|c: char| !c.is_alphanumeric());
  1220→                if clean_word.len() > 2 && !stop_words.contains(&clean_word) {
  1221→                    term_context.insert(clean_word.to_string());
  1222→                }
  1223→            }
  1224→        }
  1225→
  1226→        // Score all nodes based on context overlap
  1227→        for node in self.graph.node_weights() {
  1228→            if mentioning_nodes.contains(&node) {
  1229→                continue; // Skip nodes that directly mention the term
  1230→            }
  1231→
  1232→            let node_words: std::collections::HashSet<String> = node
  1233→                .content
  1234→                .to_lowercase()
  1235→                .split_whitespace()
  1236→                .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()).to_string())
  1237→                .filter(|w| w.len() > 2 && !stop_words.contains(&w.as_str()))
  1238→                .collect();
  1239→
  1240→            let overlap = term_context.intersection(&node_words).count();
  1241→            if overlap > 0 {
  1242→                let score = overlap as f32 / term_context.len().max(1) as f32;
  1243→                scored_nodes.push((node, score));
  1244→            }
  1245→        }
  1246→
  1247→        // Sort by score descending
  1248→        scored_nodes.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
  1249→        scored_nodes
  1250→    }
