  1252→    /// Detect potential synonym pairs based on graph structure.
  1253→    /// Nodes that share similar connections might be semantically related.
  1254→    pub fn detect_potential_synonyms(&self) -> Vec<(SpecNodeData, SpecNodeData, f32)> {
  1255→        let mut candidates = Vec::new();
  1256→        let definition_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
  1257→            .graph
  1258→            .node_indices()
  1259→            .map(|idx| (idx, &self.graph[idx]))
  1260→            .filter(|(_, n)| n.kind == NodeKind::Definition)
  1261→            .collect();
  1262→
  1263→        for i in 0..definition_nodes.len() {
  1264→            for j in (i + 1)..definition_nodes.len() {
  1265→                let (idx_a, node_a) = definition_nodes[i];
  1266→                let (idx_b, node_b) = definition_nodes[j];
  1267→
  1268→                // Skip if already marked as synonyms
  1269→                let already_synonyms = self
  1270→                    .graph
  1271→                    .edges_directed(idx_a, Direction::Outgoing)
  1272→                    .chain(self.graph.edges_directed(idx_a, Direction::Incoming))
  1273→                    .any(|e| {
  1274→                        self.graph[e.id()].kind == EdgeKind::Synonym
  1275→                            && (e.source() == idx_b || e.target() == idx_b)
  1276→                    });
  1277→
  1278→                if already_synonyms {
  1279→                    continue;
  1280→                }
  1281→
  1282→                // Calculate structural similarity (Jaccard similarity of neighbors)
  1283→                let neighbors_a: std::collections::HashSet<NodeIndex> = self
  1284→                    .graph
  1285→                    .neighbors_undirected(idx_a)
  1286→                    .collect();
  1287→                let neighbors_b: std::collections::HashSet<NodeIndex> = self
  1288→                    .graph
  1289→                    .neighbors_undirected(idx_b)
  1290→                    .collect();
  1291→
  1292→                if neighbors_a.is_empty() && neighbors_b.is_empty() {
  1293→                    continue;
  1294→                }
  1295→
  1296→                let intersection = neighbors_a.intersection(&neighbors_b).count();
  1297→                let union = neighbors_a.union(&neighbors_b).count();
  1298→
  1299→                if union > 0 {
  1300→                    let similarity = intersection as f32 / union as f32;
  1301→                    if similarity > 0.3 {
  1302→                        // Threshold for potential synonyms
  1303→                        candidates.push((node_a.clone(), node_b.clone(), similarity));
  1304→                    }
  1305→                }
  1306→            }
  1307→        }
  1308→
  1309→        candidates.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
  1310→        candidates
  1311→    }
