  1439→    /// Calculate compliance score between a specification and code snippet.
  1440→    /// Returns score 0.0-1.0 based on semantic similarity.
  1441→    pub fn calculate_compliance(&self, node_id: &str, code: &str) -> Option<ComplianceScore> {
  1442→        let node = self.get_node(node_id)?;
  1443→
  1444→        // Extract keywords from specification
  1445→        let spec_keywords = self.extract_keywords(&node.content);
  1446→        let code_keywords = self.extract_keywords(code);
  1447→
  1448→        if spec_keywords.is_empty() {
  1449→            return Some(ComplianceScore {
  1450→                score: 0.0,
  1451→                keyword_overlap: 0.0,
  1452→                structural_match: 0.0,
  1453→                explanation: "Specification has no extractable keywords".to_string(),
  1454→            });
  1455→        }
  1456→
  1457→        // Calculate keyword overlap (Jaccard similarity)
  1458→        let intersection = spec_keywords.intersection(&code_keywords).count();
  1459→        let union = spec_keywords.union(&code_keywords).count();
  1460→        let keyword_overlap = if union > 0 {
  1461→            intersection as f32 / union as f32
  1462→        } else {
  1463→            0.0
  1464→        };
  1465→
  1466→        // Structural matching for constraints/scenarios
  1467→        let structural_match = match node.kind {
  1468→            NodeKind::Constraint => self.match_constraint_structure(&node.content, code),
  1469→            NodeKind::Scenario => self.match_scenario_structure(&node.content, code),
  1470→            _ => 0.5, // Neutral for other types
  1471→        };
  1472→
  1473→        // Weighted average (60% keywords, 40% structure)
  1474→        let score = keyword_overlap * 0.6 + structural_match * 0.4;
  1475→
  1476→        let explanation = if score > 0.8 {
  1477→            "Strong compliance - code closely matches specification".to_string()
  1478→        } else if score > 0.5 {
  1479→            "Moderate compliance - code partially matches specification".to_string()
  1480→        } else if score > 0.2 {
  1481→            "Weak compliance - code loosely relates to specification".to_string()
  1482→        } else {
  1483→            "Poor compliance - code does not match specification".to_string()
  1484→        };
  1485→
  1486→        Some(ComplianceScore {
  1487→            score,
  1488→            keyword_overlap,
  1489→            structural_match,
  1490→            explanation,
  1491→        })
  1492→    }
