  1494→    fn extract_keywords(&self, text: &str) -> std::collections::HashSet<String> {
  1495→        let stop_words = [
  1496→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
  1497→            "is", "are", "was", "were", "be", "been", "being", "have", "has", "had",
  1498→            "do", "does", "did", "will", "would", "should", "could", "may", "might",
  1499→            "must", "can", "of", "by", "with", "from", "as", "into", "through"
  1500→        ];
  1501→
  1502→        text.to_lowercase()
  1503→            .split_whitespace()
  1504→            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()))
