  1510→    fn match_constraint_structure(&self, spec: &str, code: &str) -> f32 {
  1511→        let spec_lower = spec.to_lowercase();
  1512→        let code_lower = code.to_lowercase();
  1513→
  1514→        let mut score: f32 = 0.0;
  1515→
  1516→        // Look for constraint patterns
  1517→        if (spec_lower.contains("must") || spec_lower.contains("should"))
  1518→            && (code_lower.contains("assert") || code_lower.contains("require")
  1519→                || code_lower.contains("invariant"))
  1520→        {
  1521→            score += 0.3;
  1522→        }
  1523→
  1524→        // Look for comparison operators
  1525→        if (spec_lower.contains('>') || spec_lower.contains('<') || spec_lower.contains("greater")
  1526→            || spec_lower.contains("less"))
  1527→            && (code_lower.contains('>') || code_lower.contains('<'))
  1528→        {
  1529→            score += 0.2;
  1530→        }
  1531→
  1532→        // Look for equality checks
  1533→        if (spec_lower.contains("equal") || spec_lower.contains("same"))
  1534→            && (code_lower.contains("==") || code_lower.contains("equals"))
  1535→        {
  1536→            score += 0.2;
  1537→        }
  1538→
  1539→        // Look for boundary conditions
  1540→        if (spec_lower.contains("not") || spec_lower.contains("never"))
  1541→            && (code_lower.contains('!') || code_lower.contains("not"))
  1542→        {
  1543→            score += 0.3;
  1544→        }
  1545→
  1546→        score.min(1.0)
  1547→    }
  1548→
  1549→    fn match_scenario_structure(&self, spec: &str, code: &str) -> f32 {
  1550→        let spec_lower = spec.to_lowercase();
  1551→        let code_lower = code.to_lowercase();
  1552→
  1553→        let mut score: f32 = 0.0;
  1554→
  1555→        // Look for action words
  1556→        let action_words = ["login", "create", "update", "delete", "send", "receive", "verify"];
  1557→        let has_action = action_words.iter().any(|&w| spec_lower.contains(w) && code_lower.contains(w));
  1558→        if has_action {
  1559→            score += 0.4;
  1560→        }
  1561→
  1562→        // Look for test structure
  1563→        if code_lower.contains("test") || code_lower.contains("scenario") {
  1564→            score += 0.2;
  1565→        }
  1566→
  1567→        // Look for setup/action/verify pattern
  1568→        let has_setup = code_lower.contains("setup") || code_lower.contains("given");
  1569→        let has_action_code = code_lower.contains("when") || code_lower.contains("act");
  1570→        let has_verify = code_lower.contains("assert") || code_lower.contains("verify")
  1571→            || code_lower.contains("expect");
  1572→
  1573→        if has_setup { score += 0.1; }
  1574→        if has_action_code { score += 0.15; }
  1575→        if has_verify { score += 0.15; }
  1576→
  1577→        score.min(1.0)
  1578→    }
