  1580→    /// Get compliance report for all specifications with linked code.
  1581→    pub fn get_compliance_report(&self) -> Vec<(SpecNodeData, ComplianceScore)> {
  1582→        self.graph
  1583→            .node_weights()
  1584→            .filter(|n| n.metadata.contains_key("impl_code") || n.metadata.contains_key("test_code"))
  1585→            .filter_map(|n| {
  1586→                let code = n.metadata.get("impl_code")
  1587→                    .or_else(|| n.metadata.get("test_code"))?;
  1588→                let score = self.calculate_compliance(&n.id, code)?;
  1589→                Some((n.clone(), score))
