  1594→    /// Query graph state at a specific timestamp.
  1595→    /// Returns nodes and edges that existed at that time.
  1596→    pub fn query_at_timestamp(&self, timestamp: i64) -> TemporalSnapshot {
  1597→        let nodes: Vec<SpecNodeData> = self
  1598→            .graph
  1599→            .node_weights()
  1600→            .filter(|n| n.created_at <= timestamp)
  1601→            .cloned()
  1602→            .collect();
  1603→
  1604→        let edges: Vec<SpecEdgeData> = self
  1605→            .graph
  1606→            .edge_indices()
  1607→            .filter_map(|eidx| {
  1608→                let edge = &self.graph[eidx];
  1609→                if edge.created_at <= timestamp {
  1610→                    Some(edge.clone())
  1611→                } else {
  1612→                    None
  1613→                }
  1614→            })
  1615→            .collect();
  1616→
  1617→        let node_count = nodes.len();
  1618→        let edge_count = edges.len();
  1619→
  1620→        TemporalSnapshot {
  1621→            timestamp,
  1622→            nodes,
  1623→            edges,
  1624→            node_count,
  1625→            edge_count,
  1626→        }
  1627→    }
