  1629→    /// Diff graph state between two timestamps.
  1630→    /// Shows what was added, modified, or removed.
  1631→    pub fn diff_timestamps(&self, from_timestamp: i64, to_timestamp: i64) -> TemporalDiff {
  1632→        let from_snapshot = self.query_at_timestamp(from_timestamp);
  1633→        let to_snapshot = self.query_at_timestamp(to_timestamp);
  1634→
  1635→        let from_node_ids: std::collections::HashSet<String> =
  1636→            from_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
  1637→        let to_node_ids: std::collections::HashSet<String> =
  1638→            to_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
  1639→
  1640→        let added_nodes: Vec<SpecNodeData> = to_snapshot
  1641→            .nodes
  1642→            .iter()
  1643→            .filter(|n| !from_node_ids.contains(&n.id))
  1644→            .cloned()
  1645→            .collect();
  1646→
  1647→        let removed_nodes: Vec<SpecNodeData> = from_snapshot
  1648→            .nodes
  1649→            .iter()
  1650→            .filter(|n| !to_node_ids.contains(&n.id))
  1651→            .cloned()
  1652→            .collect();
  1653→
  1654→        let modified_nodes: Vec<(SpecNodeData, SpecNodeData)> = to_snapshot
  1655→            .nodes
  1656→            .iter()
  1657→            .filter_map(|to_node| {
  1658→                from_snapshot
  1659→                    .nodes
  1660→                    .iter()
  1661→                    .find(|from_node| from_node.id == to_node.id)
  1662→                    .and_then(|from_node| {
  1663→                        if from_node.modified_at < to_node.modified_at {
  1664→                            Some((from_node.clone(), to_node.clone()))
  1665→                        } else {
  1666→                            None
  1667→                        }
  1668→                    })
  1669→            })
  1670→            .collect();
  1671→
  1672→        let from_edge_ids: std::collections::HashSet<String> =
  1673→            from_snapshot.edges.iter().map(|e| e.id.clone()).collect();
  1674→        let to_edge_ids: std::collections::HashSet<String> =
  1675→            to_snapshot.edges.iter().map(|e| e.id.clone()).collect();
  1676→
  1677→        let added_edges: Vec<SpecEdgeData> = to_snapshot
  1678→            .edges
  1679→            .iter()
  1680→            .filter(|e| !from_edge_ids.contains(&e.id))
  1681→            .cloned()
  1682→            .collect();
  1683→
  1684→        let removed_edges: Vec<SpecEdgeData> = from_snapshot
  1685→            .edges
  1686→            .iter()
  1687→            .filter(|e| !to_edge_ids.contains(&e.id))
  1688→            .cloned()
  1689→            .collect();
  1690→
  1691→        TemporalDiff {
  1692→            from_timestamp,
  1693→            to_timestamp,
  1694→            added_nodes,
  1695→            removed_nodes,
  1696→            modified_nodes,
  1697→            added_edges,
  1698→            removed_edges,
  1699→        }
  1700→    }
