  1702→    /// Get evolution history of a specific node.
  1703→    /// Returns timeline of changes to the node.
  1704→    pub fn get_node_history(&self, node_id: &str) -> Option<NodeHistory> {
  1705→        let node = self.get_node(node_id)?;
  1706→
  1707→        let mut events = Vec::new();
  1708→
  1709→        // Creation event
  1710→        events.push(HistoryEvent {
  1711→            timestamp: node.created_at,
  1712→            event_type: "created".to_string(),
  1713→            description: format!("Node created: {}", node.content),
  1714→        });
  1715→
  1716→        // Modification event (if modified after creation)
  1717→        if node.modified_at > node.created_at {
  1718→            events.push(HistoryEvent {
  1719→                timestamp: node.modified_at,
  1720→                event_type: "modified".to_string(),
  1721→                description: "Node content or metadata modified".to_string(),
  1722→            });
  1723→        }
  1724→
  1725→        // Edge creation events
  1726→        if let Some(&idx) = self.id_to_index.get(node_id) {
  1727→            for edge in self
  1728→                .graph
  1729→                .edges_directed(idx, Direction::Outgoing)
  1730→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
  1731→            {
  1732→                let edge_data = &self.graph[edge.id()];
  1733→                events.push(HistoryEvent {
  1734→                    timestamp: edge_data.created_at,
  1735→                    event_type: "edge_added".to_string(),
  1736→                    description: format!("Edge added: {:?}", edge_data.kind),
  1737→                });
  1738→            }
  1739→        }
  1740→
  1741→        // Sort events by timestamp
  1742→        events.sort_by_key(|e| e.timestamp);
  1743→
  1744→        Some(NodeHistory {
  1745→            node: node.clone(),
  1746→            events,
  1747→        })
  1748→    }
