  1750→    /// Track compliance trend over time for nodes with historical compliance data.
  1751→    /// Requires compliance scores stored in metadata with timestamps.
  1752→    pub fn get_compliance_trend(&self, node_id: &str) -> Option<ComplianceTrend> {
  1753→        let node = self.get_node(node_id)?;
  1754→
  1755→        // Extract compliance history from metadata (format: "compliance_<timestamp>")
  1756→        let mut data_points: Vec<ComplianceDataPoint> = node
  1757→            .metadata
  1758→            .iter()
  1759→            .filter_map(|(key, value)| {
  1760→                if key.starts_with("compliance_") {
  1761→                    let timestamp_str = key.strip_prefix("compliance_")?;
  1762→                    let timestamp: i64 = timestamp_str.parse().ok()?;
  1763→                    let score: f32 = value.parse().ok()?;
  1764→                    Some(ComplianceDataPoint { timestamp, score })
  1765→                } else {
  1766→                    None
  1767→                }
  1768→            })
  1769→            .collect();
  1770→
  1771→        if data_points.is_empty() {
  1772→            return None;
  1773→        }
  1774→
  1775→        // Sort by timestamp
  1776→        data_points.sort_by_key(|d| d.timestamp);
  1777→
  1778→        let trend_direction = if data_points.len() >= 2 {
  1779→            let first = data_points[0].score;
  1780→            let last = data_points[data_points.len() - 1].score;
  1781→            if last > first + 0.1 {
  1782→                "improving".to_string()
  1783→            } else if last < first - 0.1 {
  1784→                "degrading".to_string()
  1785→            } else {
  1786→                "stable".to_string()
  1787→            }
  1788→        } else {
  1789→            "unknown".to_string()
  1790→        };
  1791→
  1792→        Some(ComplianceTrend {
  1793→            node: node.clone(),
  1794→            data_points,
  1795→            trend_direction,
  1796→        })
  1797→    }
