  1800→    /// Nodes are colored by formality layer (U0=blue, U1=green, U2=yellow, U3=red).
  1801→    /// Edges are styled by kind (Refines, Formalizes, etc.).
  1802→    pub fn export_dot(&self) -> String {
  1803→        let mut dot = String::from("digraph spec_oracle {\n");
  1804→        dot.push_str("    rankdir=LR;\n");
  1805→        dot.push_str("    node [shape=box, style=filled];\n");
  1806→        dot.push_str("    edge [fontsize=10];\n\n");
  1807→
  1808→        // Helper function to escape DOT strings
  1809→        fn escape_dot(s: &str) -> String {
  1810→            s.replace('\\', "\\\\")
  1811→                .replace('"', "\\\"")
  1812→                .replace('\n', "\\n")
  1813→        }
  1814→
  1815→        // Helper function to truncate content
  1816→        fn truncate(s: &str, max_len: usize) -> String {
  1817→            if s.len() > max_len {
  1818→                format!("{}...", &s[..max_len])
  1819→            } else {
  1820→                s.to_string()
  1821→            }
  1822→        }
  1823→
  1824→        // Helper function to get layer color
  1825→        fn layer_color(layer: u8) -> &'static str {
  1826→            match layer {
  1827→                0 => "lightblue",   // U0: natural language
  1828→                1 => "lightgreen",  // U1: structured/formal
  1829→                2 => "lightyellow", // U2: interface/API
  1830→                3 => "lightcoral",  // U3: implementation
  1831→                _ => "white",
  1832→            }
  1833→        }
  1834→
  1835→        // Helper function to get layer label
  1836→        fn layer_label(layer: u8) -> &'static str {
  1837→            match layer {
  1838→                0 => "U0",
  1839→                1 => "U1",
  1840→                2 => "U2",
  1841→                3 => "U3",
  1842→                _ => "U?",
  1843→            }
  1844→        }
  1845→
  1846→        // Helper function to get kind abbreviation
  1847→        fn kind_abbr(kind: NodeKind) -> &'static str {
  1848→            match kind {
  1849→                NodeKind::Assertion => "A",
  1850→                NodeKind::Constraint => "C",
  1851→                NodeKind::Scenario => "S",
  1852→                NodeKind::Definition => "D",
  1853→                NodeKind::Domain => "Dom",
  1854→            }
  1855→        }
  1856→
  1857→        // Add nodes
  1858→        for node in self.graph.node_weights() {
  1859→            let layer = node.formality_layer;
  1860→            let color = layer_color(layer);
  1861→            let layer_lbl = layer_label(layer);
  1862→            let kind_lbl = kind_abbr(node.kind);
  1863→            let content_short = truncate(&node.content, 50);
  1864→            let label = format!("[{}] {} {}", layer_lbl, kind_lbl, content_short);
  1865→
  1866→            dot.push_str(&format!(
  1867→                "    \"{}\" [label=\"{}\", fillcolor=\"{}\"];\n",
  1868→                escape_dot(&node.id),
  1869→                escape_dot(&label),
  1870→                color
  1871→            ));
  1872→        }
  1873→
  1874→        dot.push('\n');
  1875→
  1876→        // Add edges
  1877→        for edge_idx in self.graph.edge_indices() {
  1878→            if let Some((source_idx, target_idx)) = self.graph.edge_endpoints(edge_idx) {
  1879→                if let Some(edge) = self.graph.edge_weight(edge_idx) {
  1880→                    if let (Some(source_node), Some(target_node)) = (
  1881→                        self.graph.node_weight(source_idx),
  1882→                        self.graph.node_weight(target_idx),
  1883→                    ) {
  1884→                        let edge_style = match edge.kind {
  1885→                            EdgeKind::Refines => "solid",
  1886→                            EdgeKind::Formalizes => "bold",
  1887→                            EdgeKind::DerivesFrom => "dashed",
  1888→                            EdgeKind::Transform => "dotted",
  1889→                            EdgeKind::Contradicts => "bold, color=red",
  1890→                            EdgeKind::DependsOn => "dashed",
  1891→                            EdgeKind::Synonym => "dotted, color=gray",
  1892→                            EdgeKind::Composes => "solid",
  1893→                        };
  1894→
  1895→                        let edge_label = format!("{:?}", edge.kind);
  1896→
  1897→                        dot.push_str(&format!(
  1898→                            "    \"{}\" -> \"{}\" [label=\"{}\", style=\"{}\"];\n",
  1899→                            escape_dot(&source_node.id),
  1900→                            escape_dot(&target_node.id),
  1901→                            edge_label,
  1902→                            edge_style
  1903→                        ));
  1904→                    }
  1905→                }
  1906→            }
  1907→        }
  1908→
  1909→        dot.push_str("}\n");
  1910→        dot
  1911→    }
  1912→}
