   292→            let mut meta_with_desc = meta.clone();
   293→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   294→
   295→            constraints.push(Constraint {
   296→                // Layer 2: Proof data
   297→                formal: Some(format!(">= {}", min_value)),
   298→                kind: ConstraintKind::Universal,
   299→                // OLD fields (for compatibility)
   300→                description: Some(description_text),
   301→                metadata: Some(meta),
   302→                // NEW field (preferred)
   303→                meta: Some(meta_with_desc),
   304→            });
   305→        }
   306→
   307→        // Pattern 2: "at most N"
   308→        if let Some(max_value) = self.extract_numeric_value(&lower_text, "at most") {
   309→            let mut meta = ConstraintMetadata::new();
   310→            meta.set_pattern("at_most".to_string());
   311→            meta.set_value(max_value.to_string());
   312→            meta.set_source(text.to_string());
   313→
   314→            let description_text = format!("Maximum value: {}", max_value);
   315→            let mut meta_with_desc = meta.clone();
   316→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   317→
   318→            constraints.push(Constraint {
   319→                formal: Some(format!("<= {}", max_value)),
   320→                kind: ConstraintKind::Universal,
   321→                description: Some(description_text),
   322→                metadata: Some(meta),
   323→                meta: Some(meta_with_desc),
   324→            });
   325→        }
   326→
   327→        // Pattern 3: "minimum N" / "minimum of N"
   328→        if let Some(min_value) = self.extract_numeric_value(&lower_text, "minimum") {
   329→            let mut meta = ConstraintMetadata::new();
   330→            meta.set_pattern("minimum".to_string());
   331→            meta.set_value(min_value.to_string());
   332→            meta.set_source(text.to_string());
   333→
   334→            let description_text = format!("Minimum value: {}", min_value);
   335→            let mut meta_with_desc = meta.clone();
   336→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   337→
   338→            constraints.push(Constraint {
   339→                formal: Some(format!(">= {}", min_value)),
   340→                kind: ConstraintKind::Universal,
   341→                description: Some(description_text),
   342→                metadata: Some(meta),
   343→                meta: Some(meta_with_desc),
   344→            });
   345→        }
   346→
   347→        // Pattern 4: "maximum N" / "maximum of N"
   348→        if let Some(max_value) = self.extract_numeric_value(&lower_text, "maximum") {
   349→            let mut meta = ConstraintMetadata::new();
   350→            meta.set_pattern("maximum".to_string());
   351→            meta.set_value(max_value.to_string());
   352→            meta.set_source(text.to_string());
   353→
   354→            let description_text = format!("Maximum value: {}", max_value);
   355→            let mut meta_with_desc = meta.clone();
   356→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   357→
   358→            constraints.push(Constraint {
   359→                formal: Some(format!("<= {}", max_value)),
   360→                kind: ConstraintKind::Universal,
   361→                description: Some(description_text),
   362→                metadata: Some(meta),
   363→                meta: Some(meta_with_desc),
   364→            });
   365→        }
   366→
   367→        // Pattern 5: "exactly N"
   368→        if let Some(exact_value) = self.extract_numeric_value(&lower_text, "exactly") {
   369→            let mut meta = ConstraintMetadata::new();
   370→            meta.set_pattern("exactly".to_string());
   371→            meta.set_value(exact_value.to_string());
   372→            meta.set_source(text.to_string());
   373→
   374→            let description_text = format!("Exact value: {}", exact_value);
   375→            let mut meta_with_desc = meta.clone();
   376→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   377→
   378→            constraints.push(Constraint {
   379→                formal: Some(format!("== {}", exact_value)),
   380→                kind: ConstraintKind::Universal,
   381→                description: Some(description_text),
   382→                metadata: Some(meta),
   383→                meta: Some(meta_with_desc),
   384→            });
   385→        }
   386→
   387→        // Pattern 6: "between X and Y"
   388→        if let Some((min, max)) = self.extract_range(&lower_text) {
   389→            let mut meta = ConstraintMetadata::new();
   390→            meta.set_pattern("range".to_string());
   391→            meta.set_min(min.to_string());
   392→            meta.set_max(max.to_string());
   393→            meta.set_source(text.to_string());
   394→
   395→            let description_text = format!("Range: {} to {}", min, max);
   396→            let mut meta_with_desc = meta.clone();
   397→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   398→
   399→            constraints.push(Constraint {
   400→                formal: Some(format!(">= {} && <= {}", min, max)),
   401→                kind: ConstraintKind::Universal,
   402→                description: Some(description_text),
   403→                metadata: Some(meta),
   404→                meta: Some(meta_with_desc),
   405→            });
   406→        }
   407→
   408→        // Pattern 7: "must be" (boolean requirement)
   409→        if lower_text.contains("must be") && !lower_text.contains("at least") && !lower_text.contains("at most") {
   410→            // Extract what must be
   411→            if let Some(pos) = lower_text.find("must be") {
   412→                let after = &text[pos + 7..].trim();
   413→                if !after.is_empty() {
   414→                    let mut meta = ConstraintMetadata::new();
   415→                    meta.set_pattern("must_be".to_string());
   416→                    meta.set_value(after.to_string());
   417→                    meta.set_source(text.to_string());
   418→
   419→                    let description_text = format!("Required: {}", after);
   420→                    let mut meta_with_desc = meta.clone();
   421→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   422→
   423→                    constraints.push(Constraint {
   424→                        formal: Some(format!("== {}", after)),
   425→                        kind: ConstraintKind::Universal,
   426→                        description: Some(description_text),
   427→                        metadata: Some(meta),
   428→                        meta: Some(meta_with_desc),
   429→                    });
   430→                }
   431→            }
   432→        }
   433→
   434→        // Pattern 8: "must not be" / "cannot be" (boolean prohibition)
   435→        if lower_text.contains("must not") || lower_text.contains("cannot be") {
   436→            let pattern = if lower_text.contains("must not") { "must not" } else { "cannot be" };
   437→            if let Some(pos) = lower_text.find(pattern) {
   438→                let after = &text[pos + pattern.len()..].trim();
   439→                if !after.is_empty() {
   440→                    let mut meta = ConstraintMetadata::new();
   441→                    meta.set_pattern("must_not_be".to_string());
   442→                    meta.set_value(after.to_string());
   443→                    meta.set_source(text.to_string());
   444→
   445→                    let description_text = format!("Forbidden: {}", after);
   446→                    let mut meta_with_desc = meta.clone();
   447→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   448→
   449→                    constraints.push(Constraint {
   450→                        formal: Some(format!("!= {}", after)),
   451→                        kind: ConstraintKind::Universal,
   452→                        description: Some(description_text),
   453→                        metadata: Some(meta),
   454→                        meta: Some(meta_with_desc),
   455→                    });
   456→                }
   457→            }
   458→        }
   459→
   460→        constraints
   461→    }
