   473→        // Check if specs are explicitly marked as contradicting
   474→        let a_contradicts_b = if let Some(proof_data) = &spec_a.proof_data {
   475→            proof_data.contradicts.contains(&spec_b.spec_id)
   476→        } else if let Some(contradicts) = &spec_a.contradicts {
   477→            contradicts.contains(&spec_b.spec_id)
   478→        } else {
   479→            false
   480→        };
   481→
   482→        if a_contradicts_b {
   483→            steps.push(ProofStep {
   484→                description: "Specifications explicitly contradict each other".to_string(),
   485→                justification: "Explicit contradiction marker".to_string(),
   486→            });
   487→            return (ProofStatus::Refuted, steps);
   488→        }
   489→
   490→        // Basic heuristic checks
   491→        let contradictory = self.detect_obvious_contradiction(constraints_a, constraints_b);
   492→
   493→        if contradictory {
   494→            steps.push(ProofStep {
   495→                description: "Detected obvious contradiction in constraints".to_string(),
   496→                justification: "Constraint conflict analysis".to_string(),
   497→            });
   498→            (ProofStatus::Refuted, steps)
   499→        } else {
   500→            steps.push(ProofStep {
   501→                description: "No obvious contradiction detected".to_string(),
   502→                justification: "Heuristic constraint analysis".to_string(),
   503→            });
   504→            steps.push(ProofStep {
   505→                description: "Note: This is not a complete proof. SMT solver integration needed for soundness.".to_string(),
   506→                justification: "Limitation acknowledgment".to_string(),
   507→            });
