   516→    ) -> (ProofStatus, Vec<ProofStep>) {
   517→        let mut steps = Vec::new();
   518→
   519→        // Get constraints from new structure first, fall back to old structure
   520→        let constraints = if let Some(proof_data) = &spec.proof_data {
   521→            &proof_data.constraints
   522→        } else if let Some(constraints) = &spec.constraints {
   523→            constraints
   524→        } else {
   525→            &vec![]
   526→        };
