   731→    /// Heuristically detect underspecification (漏れA)
   732→    ///
   733→    /// Returns confidence-scored report, not a formal proof.
   734→    /// Underspecification is a design choice, not an error, so it cannot be formally proven wrong.
   735→    pub fn detect_underspecification(
   736→        &self,
   737→        spec: &crate::formal::AdmissibleSet,
   738→        domain: &crate::formal::Domain,
   739→        _universe: &crate::formal::Universe,
   740→    ) -> UnderspecificationReport {
   741→        let mut confidence = 0.0f32;
   742→        let mut reasons = Vec::new();
   743→        let mut suggestions = Vec::new();
   744→
   745→        // Get constraints
   746→        let spec_constraints = if let Some(proof_data) = &spec.proof_data {
   747→            &proof_data.constraints
   748→        } else if let Some(constraints) = &spec.constraints {
   749→            constraints
   750→        } else {
   751→            &vec![]
   752→        };
   753→
   754→        let domain_constraints = if let Some(proof_data) = &domain.proof_data {
   755→            &proof_data.constraints
   756→        } else {
   757→            &vec![]
   758→        };
   759→
   760→        // Heuristic 1: Constraint count
   761→        // If spec has very few constraints relative to domain complexity
   762→        if spec_constraints.is_empty() {
   763→            confidence += 0.8;
   764→            reasons.push("Specification has no constraints".to_string());
   765→            suggestions.push("Add constraints to define the admissible set".to_string());
   766→        } else if spec_constraints.len() < 3 && !domain_constraints.is_empty() && domain_constraints.len() > spec_constraints.len() * 2 {
   767→            confidence += 0.4;
   768→            reasons.push(format!(
   769→                "Specification has only {} constraints, but domain has {} constraints",
   770→                spec_constraints.len(),
   771→                domain_constraints.len()
   772→            ));
   773→            suggestions.push("Consider adding more constraints to narrow the admissible set".to_string());
   774→        }
   775→
   776→        // Heuristic 2: Free variables
   777→        // Extract variable names from domain and spec
   778→        let domain_vars = self.extract_variable_names_from_constraints(domain_constraints);
   779→        let spec_vars = self.extract_variable_names_from_constraints(spec_constraints);
   780→
   781→        let unconstrained_vars: Vec<_> = domain_vars.iter()
   782→            .filter(|v| !spec_vars.contains(*v))
   783→            .collect();
   784→
   785→        if !unconstrained_vars.is_empty() {
   786→            confidence += 0.3 * (unconstrained_vars.len() as f32 / domain_vars.len().max(1) as f32);
   787→            reasons.push(format!(
   788→                "Domain mentions {} variable(s) not constrained in spec: {:?}",
   789→                unconstrained_vars.len(),
   790→                unconstrained_vars
   791→            ));
   792→            suggestions.push("Add constraints for unconstrained variables".to_string());
   793→        }
   794→
   795→        // Heuristic 3: Keyword matching
   796→        // Check if domain description mentions aspects not addressed in spec
   797→        let domain_desc = if let Some(meta) = &domain.meta {
   798→            meta.get_str("description").map(|s| s.as_str()).unwrap_or("")
   799→        } else if let Some(desc) = &domain.description {
   800→            desc.as_str()
   801→        } else {
   802→            ""
   803→        };
   804→
   805→        let keywords = vec!["security", "performance", "reliability", "availability", "scalability"];
   806→        let domain_lower = domain_desc.to_lowercase();
   807→        let spec_text = spec_constraints.iter()
   808→            .filter_map(|c| {
   809→                if let Some(meta) = &c.meta {
   810→                    meta.get_str("description").map(|s| s.to_lowercase())
   811→                } else {
   812→                    c.description.as_ref().map(|s| s.to_lowercase())
   813→                }
   814→            })
   815→            .collect::<Vec<_>>()
   816→            .join(" ");
   817→
   818→        for keyword in keywords {
   819→            if domain_lower.contains(keyword) && !spec_text.contains(keyword) {
   820→                confidence += 0.1;
   821→                reasons.push(format!(
   822→                    "Domain mentions '{}' but specification does not address it",
   823→                    keyword
   824→                ));
   825→                suggestions.push(format!("Add constraints related to {}", keyword));
   826→            }
   827→        }
   828→
   829→        // Heuristic 4: Constraint tightness
   830→        // Check if constraints are very loose (wide ranges, weak requirements)
   831→        let loose_constraints = spec_constraints.iter().filter(|c| {
   832→            let desc = if let Some(meta) = &c.meta {
   833→                meta.get_str("description").map(|s| s.as_str()).unwrap_or("")
   834→            } else {
   835→                c.description.as_deref().unwrap_or("")
   836→            };
   837→            let lower = desc.to_lowercase();
   838→            // Very loose patterns: "at least 1", "at most 1000000", etc.
   839→            (lower.contains("at least 1") && !lower.contains("at least 10")) ||
   840→            lower.contains("at most 1000") ||
   841→            lower.contains("any") ||
   842→            lower.contains("optional")
   843→        }).count();
   844→
   845→        if loose_constraints > 0 {
   846→            confidence += 0.2 * (loose_constraints as f32 / spec_constraints.len().max(1) as f32);
   847→            reasons.push(format!(
   848→                "{} constraint(s) appear very loose or permissive",
   849→                loose_constraints
   850→            ));
   851→            suggestions.push("Consider tightening loose constraints".to_string());
   852→        }
   853→
   854→        // Cap confidence at 1.0
   855→        confidence = confidence.min(1.0);
   856→
   857→        let is_likely_underspecified = confidence >= 0.5;
   858→
   859→        UnderspecificationReport {
   860→            spec_id: spec.spec_id.as_str().to_string(),
   861→            domain_id: domain.id.as_str().to_string(),
   862→            is_likely_underspecified,
   863→            confidence,
   864→            reasons,
   865→            suggestions,
   866→        }
   867→    }
