   869→    /// Extract variable names from constraints
   870→    fn extract_variable_names_from_constraints(&self, constraints: &[crate::formal::Constraint]) -> HashSet<String> {
   871→        let mut vars = HashSet::new();
   872→        for constraint in constraints {
   873→            let desc = if let Some(meta) = &constraint.meta {
   874→                meta.get_str("description").map(|s| s.as_str()).unwrap_or("")
   875→            } else {
   876→                constraint.description.as_deref().unwrap_or("")
   877→            };
   878→
   879→            // Extract variable name (heuristic: word before "must", "should", "is", etc.)
   880→            let words: Vec<&str> = desc.split_whitespace().collect();
   881→            for (i, &word) in words.iter().enumerate() {
   882→                if word == "must" || word == "should" || word == "is" {
   883→                    if i > 0 {
   884→                        vars.insert(words[i-1].to_lowercase().trim_matches(|c: char| !c.is_alphanumeric()).to_string());
   885→                    }
   886→                }
   887→            }
   888→        }
   889→        vars
   890→    }
   891→}
