     1→/// SpecRepository: Pure data persistence layer for specification graph
     2→///
     3→/// This module contains ALL pure data operations:
     4→/// - CRUD on nodes and edges
     5→/// - Graph traversal and queries
     6→/// - Search and filtering
     7→/// - Test coverage and compliance calculation
     8→/// - Temporal queries (versioning, history, diff)
     9→/// - Serialization (JSON, DOT)
    10→///
    11→/// ARCHITECTURAL CONSTRAINT:
    12→/// NO imports from crate::formal:: module allowed here.
    13→/// This is pure data layer - formal verification belongs in UDAFModel.
    14→
    15→use chrono::Utc;
    16→use petgraph::graph::{DiGraph, EdgeIndex, NodeIndex};
    17→use petgraph::visit::EdgeRef;
    18→use petgraph::Direction;
    19→use serde::{Deserialize, Serialize};
    20→use std::collections::HashMap;
    21→use uuid::Uuid;
    22→
    23→use super::*; // Import data module types
    24→
    25→/// Pure data repository for specification graph
    26→#[derive(Debug, Clone, Serialize, Deserialize)]
    27→pub struct SpecRepository {
    28→    graph: DiGraph<SpecNodeData, SpecEdgeData>,
    29→    #[serde(skip)]
    30→    id_to_index: HashMap<String, NodeIndex>,
    31→    #[serde(skip)]
    32→    edge_id_to_index: HashMap<String, EdgeIndex>,
    33→}
    34→
    35→impl Default for SpecRepository {
    36→    fn default() -> Self {
    37→        Self::new()
    38→    }
    39→}
    40→
    41→impl SpecRepository {
    42→    pub fn new() -> Self {
    43→        Self {
    44→            graph: DiGraph::new(),
    45→            id_to_index: HashMap::new(),
    46→            edge_id_to_index: HashMap::new(),
    47→        }
    48→    }
    49→
    50→    /// Rebuild lookup indices after deserialization.
    51→    pub fn rebuild_indices(&mut self) {
    52→        self.id_to_index.clear();
    53→        self.edge_id_to_index.clear();
    54→        for idx in self.graph.node_indices() {
    55→            let node = &self.graph[idx];
    56→            self.id_to_index.insert(node.id.clone(), idx);
    57→        }
    58→        for idx in self.graph.edge_indices() {
    59→            let edge = &self.graph[idx];
    60→            self.edge_id_to_index.insert(edge.id.clone(), idx);
    61→        }
    62→    }
    63→
    64→    // ========================================================================
    65→    // Node operations
    66→    // ========================================================================
    67→
    68→    pub fn add_node(
    69→        &mut self,
    70→        content: String,
    71→        kind: NodeKind,
    72→        metadata: HashMap<String, String>,
    73→    ) -> &SpecNodeData {
    74→        let id = Uuid::new_v4().to_string();
    75→        let now = Utc::now().timestamp();
    76→        let data = SpecNodeData {
    77→            id: id.clone(),
    78→            content,
    79→            kind,
    80→            metadata,
    81→            created_at: now,
    82→            modified_at: now,
    83→            formality_layer: 0, // Default to natural language
    84→        };
    85→        let idx = self.graph.add_node(data);
    86→        self.id_to_index.insert(id, idx);
    87→        &self.graph[idx]
    88→    }
    89→
    90→    /// Add a node from loaded data (preserves existing ID and timestamps)
    91→    pub fn add_node_from_loaded(&mut self, node: SpecNodeData) -> String {
    92→        let id = node.id.clone();
    93→        let idx = self.graph.add_node(node);
    94→        self.id_to_index.insert(id.clone(), idx);
    95→        id
    96→    }
    97→
    98→    pub fn get_node(&self, id: &str) -> Option<&SpecNodeData> {
    99→        self.id_to_index.get(id).map(|&idx| &self.graph[idx])
   100→    }
   101→
   102→    /// Find a node by content and kind (for deduplication)
   103→    pub fn find_node_by_content(&self, content: &str, kind: NodeKind) -> Option<&SpecNodeData> {
   104→        self.graph
   105→            .node_weights()
   106→            .find(|n| n.content == content && n.kind == kind)
   107→    }
   108→
   109→    pub fn update_node_formality(&mut self, id: &str, formality_layer: u8) -> bool {
   110→        if let Some(&idx) = self.id_to_index.get(id) {
   111→            if let Some(node) = self.graph.node_weight_mut(idx) {
   112→                node.formality_layer = formality_layer;
   113→                node.modified_at = Utc::now().timestamp();
   114→                return true;
   115→            }
   116→        }
   117→        false
   118→    }
   119→
   120→    pub fn update_node_metadata(
   121→        &mut self,
   122→        id: &str,
   123→        key: String,
   124→        value: String,
   125→    ) -> Option<SpecNodeData> {
   126→        if let Some(&idx) = self.id_to_index.get(id) {
   127→            if let Some(node) = self.graph.node_weight_mut(idx) {
   128→                node.metadata.insert(key, value);
   129→                node.modified_at = Utc::now().timestamp();
   130→                return Some(node.clone());
   131→            }
   132→        }
   133→        None
   134→    }
   135→
   136→    pub fn remove_node(&mut self, id: &str) -> Option<SpecNodeData> {
   137→        if let Some(&idx) = self.id_to_index.get(id) {
   138→            // Remove related edge index entries
   139→            let edge_indices: Vec<EdgeIndex> = self
   140→                .graph
   141→                .edges_directed(idx, Direction::Outgoing)
   142→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
   143→                .map(|e| e.id())
   144→                .collect();
   145→            for eidx in edge_indices {
   146→                if let Some(edge_data) = self.graph.edge_weight(eidx) {
   147→                    self.edge_id_to_index.remove(&edge_data.id);
   148→                }
   149→            }
   150→
   151→            let data = self.graph.remove_node(idx)?;
   152→            self.id_to_index.remove(&data.id);
   153→
   154→            // After removal petgraph may swap indices; rebuild to stay consistent.
   155→            self.rebuild_indices();
   156→            Some(data)
   157→        } else {
   158→            None
   159→        }
   160→    }
   161→
   162→    pub fn list_nodes(&self, kind_filter: Option<NodeKind>) -> Vec<&SpecNodeData> {
   163→        self.graph
   164→            .node_weights()
   165→            .filter(|n| kind_filter.is_none() || Some(n.kind) == kind_filter)
   166→            .collect()
   167→    }
   168→
   169→    // ========================================================================
   170→    // Edge operations
   171→    // ========================================================================
