   173→    pub fn add_edge(
   174→        &mut self,
   175→        source_id: &str,
   176→        target_id: &str,
   177→        kind: EdgeKind,
   178→        metadata: HashMap<String, String>,
   179→    ) -> Result<&SpecEdgeData, GraphError> {
   180→        let &src_idx = self
   181→            .id_to_index
   182→            .get(source_id)
   183→            .ok_or_else(|| GraphError::NodeNotFound(source_id.to_string()))?;
   184→        let &tgt_idx = self
   185→            .id_to_index
   186→            .get(target_id)
   187→            .ok_or_else(|| GraphError::NodeNotFound(target_id.to_string()))?;
   188→
   189→        let id = Uuid::new_v4().to_string();
   190→        let now = Utc::now().timestamp();
   191→        let data = SpecEdgeData {
   192→            id: id.clone(),
   193→            kind,
   194→            metadata,
   195→            created_at: now,
   196→        };
   197→        let eidx = self.graph.add_edge(src_idx, tgt_idx, data);
   198→        self.edge_id_to_index.insert(id, eidx);
   199→        Ok(&self.graph[eidx])
   200→    }
   201→
   202→    /// Add an edge from loaded data (preserves existing ID and timestamps)
   203→    pub fn add_edge_from_loaded(&mut self, edge: Edge) -> Result<String, GraphError> {
   204→        let &src_idx = self
   205→            .id_to_index
   206→            .get(&edge.source)
   207→            .ok_or_else(|| GraphError::NodeNotFound(edge.source.clone()))?;
