   221→            let data = self.graph.remove_edge(eidx)?;
   222→            self.edge_id_to_index.remove(&data.id);
   223→            // Edge removal can invalidate other edge indices; rebuild.
   224→            self.rebuild_indices();
   225→            Some(data)
   226→        } else {
   227→            None
   228→        }
   229→    }
