   231→    pub fn list_edges(&self, node_id: Option<&str>) -> Vec<(&SpecEdgeData, &str, &str)> {
   232→        self.graph
   233→            .edge_indices()
   234→            .filter_map(|eidx| {
   235→                let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
   236→                let edge_data = &self.graph[eidx];
   237→                let src_data = &self.graph[src_idx];
   238→                let tgt_data = &self.graph[tgt_idx];
   239→                if let Some(nid) = node_id {
   240→                    if src_data.id != nid && tgt_data.id != nid {
   241→                        return None;
   242→                    }
   243→                }
   244→                Some((edge_data, src_data.id.as_str(), tgt_data.id.as_str()))
   245→            })
   246→            .collect()
   247→    }
