   317→    /// Trace all relationships for a node, returning a hierarchical structure.
   318→    /// Returns tuples of (node, edge_kind, direction) where direction is "outgoing" or "incoming".
   319→    pub fn trace_relationships(
   320→        &self,
   321→        node_id: &str,
   322→        max_depth: usize,
   323→    ) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
   324→        let mut result = Vec::new();
   325→        let mut visited = std::collections::HashSet::new();
   326→
   327→        if let Some(&start_idx) = self.id_to_index.get(node_id) {
   328→            visited.insert(start_idx);
   329→            self.trace_recursive(start_idx, max_depth, 0, &mut visited, &mut result);
   330→        }
   331→
   332→        result
   333→    }
   334→
   335→    fn trace_recursive(
   336→        &self,
   337→        idx: NodeIndex,
   338→        max_depth: usize,
   339→        current_depth: usize,
   340→        visited: &mut std::collections::HashSet<NodeIndex>,
   341→        result: &mut Vec<(SpecNodeData, EdgeKind, String, usize)>,
   342→    ) {
   343→        if max_depth > 0 && current_depth >= max_depth {
   344→            return;
   345→        }
   346→
   347→        // Traverse outgoing edges
   348→        for edge in self.graph.edges_directed(idx, Direction::Outgoing) {
   349→            let target_idx = edge.target();
   350→            let edge_data = &self.graph[edge.id()];
   351→            let target_node = &self.graph[target_idx];
   352→
   353→            result.push((
   354→                target_node.clone(),
   355→                edge_data.kind,
   356→                "outgoing".to_string(),
   357→                current_depth + 1,
   358→            ));
   359→
   360→            if !visited.contains(&target_idx) {
   361→                visited.insert(target_idx);
   362→                self.trace_recursive(target_idx, max_depth, current_depth + 1, visited, result);
   363→            }
   364→        }
   365→
   366→        // Traverse incoming edges
   367→        for edge in self.graph.edges_directed(idx, Direction::Incoming) {
   368→            let source_idx = edge.source();
   369→            let edge_data = &self.graph[edge.id()];
   370→            let source_node = &self.graph[source_idx];
   371→
   372→            result.push((
   373→                source_node.clone(),
   374→                edge_data.kind,
   375→                "incoming".to_string(),
   376→                current_depth + 1,
   377→            ));
   378→
   379→            if !visited.contains(&source_idx) {
   380→                visited.insert(source_idx);
   381→                self.trace_recursive(source_idx, max_depth, current_depth + 1, visited, result);
   382→            }
   383→        }
   384→    }
