   415→
   416→    /// Find all synonym groups: nodes connected by Synonym edges.
   417→    pub fn resolve_term(&self, term: &str) -> (Vec<&SpecNodeData>, Vec<String>) {
   418→        let t = term.to_lowercase();
   419→
   420→        // Find definition nodes matching the term
   421→        let definitions: Vec<&SpecNodeData> = self
   422→            .graph
   423→            .node_weights()
   424→            .filter(|n| n.kind == NodeKind::Definition && n.content.to_lowercase().contains(&t))
   425→            .collect();
   426→
   427→        // Collect synonyms via Synonym edges
   428→        let mut synonyms = Vec::new();
   429→        for def in &definitions {
   430→            if let Some(&idx) = self.id_to_index.get(&def.id) {
   431→                for edge in self
   432→                    .graph
   433→                    .edges_directed(idx, Direction::Outgoing)
   434→                    .chain(self.graph.edges_directed(idx, Direction::Incoming))
   435→                {
   436→                    if self.graph[edge.id()].kind == EdgeKind::Synonym {
   437→                        let other_idx = if edge.source() == idx {
   438→                            edge.target()
   439→                        } else {
   440→                            edge.source()
   441→                        };
   442→                        let other = &self.graph[other_idx];
   443→                        if !synonyms.contains(&other.content) {
   444→                            synonyms.push(other.content.clone());
   445→                        }
   446→                    }
   447→                }
   448→            }
   449→        }
   450→
   451→        (definitions, synonyms)
   452→    }
   453→
   454→    /// Find potentially related terms based on co-occurrence in metadata or content.
   455→    /// This provides a lightweight semantic clustering without requiring external AI.
   456→    pub fn find_related_terms(&self, term: &str) -> Vec<(&SpecNodeData, f32)> {
   457→        let t = term.to_lowercase();
   458→        let mut scored_nodes: Vec<(&SpecNodeData, f32)> = Vec::new();
   459→
   460→        // Find nodes that mention the term
   461→        let mentioning_nodes: Vec<&SpecNodeData> = self
   462→            .graph
   463→            .node_weights()
   464→            .filter(|n| n.content.to_lowercase().contains(&t))
   465→            .collect();
   466→
   467→        if mentioning_nodes.is_empty() {
   468→            return scored_nodes;
   469→        }
   470→
   471→        // Extract significant words from mentioning nodes (excluding common words)
   472→        let stop_words = [
   473→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
   474→        ];
   475→        let mut term_context: std::collections::HashSet<String> =
   476→            std::collections::HashSet::new();
   477→
   478→        for node in &mentioning_nodes {
   479→            for word in node.content.to_lowercase().split_whitespace() {
   480→                let clean_word = word.trim_matches(|c: char| !c.is_alphanumeric());
   481→                if clean_word.len() > 2 && !stop_words.contains(&clean_word) {
   482→                    term_context.insert(clean_word.to_string());
   483→                }
   484→            }
   485→        }
   486→
   487→        // Score all nodes based on context overlap
   488→        for node in self.graph.node_weights() {
   489→            if mentioning_nodes.contains(&node) {
   490→                continue; // Skip nodes that directly mention the term
   491→            }
   492→
   493→            let node_words: std::collections::HashSet<String> = node
   494→                .content
   495→                .to_lowercase()
   496→                .split_whitespace()
   497→                .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()).to_string())
   498→                .filter(|w| w.len() > 2 && !stop_words.contains(&w.as_str()))
   499→                .collect();
   500→
   501→            let overlap = term_context.intersection(&node_words).count();
   502→            if overlap > 0 {
   503→                let score = overlap as f32 / term_context.len().max(1) as f32;
   504→                scored_nodes.push((node, score));
   505→            }
   506→        }
   507→
   508→        // Sort by score descending
   509→        scored_nodes.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
   510→        scored_nodes
   511→    }
   512→
   513→    /// Detect potential synonym pairs based on graph structure.
   514→    /// Nodes that share similar connections might be semantically related.
   515→    pub fn detect_potential_synonyms(&self) -> Vec<(SpecNodeData, SpecNodeData, f32)> {
   516→        let mut candidates = Vec::new();
   517→        let definition_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
   518→            .graph
   519→            .node_indices()
   520→            .map(|idx| (idx, &self.graph[idx]))
   521→            .filter(|(_, n)| n.kind == NodeKind::Definition)
   522→            .collect();
   523→
   524→        for i in 0..definition_nodes.len() {
   525→            for j in (i + 1)..definition_nodes.len() {
   526→                let (idx_a, node_a) = definition_nodes[i];
   527→                let (idx_b, node_b) = definition_nodes[j];
   528→
   529→                // Skip if already marked as synonyms
   530→                let already_synonyms = self
   531→                    .graph
   532→                    .edges_directed(idx_a, Direction::Outgoing)
   533→                    .chain(self.graph.edges_directed(idx_a, Direction::Incoming))
   534→                    .any(|e| {
   535→                        self.graph[e.id()].kind == EdgeKind::Synonym
   536→                            && (e.source() == idx_b || e.target() == idx_b)
   537→                    });
   538→
   539→                if already_synonyms {
   540→                    continue;
   541→                }
   542→
   543→                // Calculate structural similarity (Jaccard similarity of neighbors)
   544→                let neighbors_a: std::collections::HashSet<NodeIndex> =
   545→                    self.graph.neighbors_undirected(idx_a).collect();
   546→                let neighbors_b: std::collections::HashSet<NodeIndex> =
   547→                    self.graph.neighbors_undirected(idx_b).collect();
   548→
   549→                if neighbors_a.is_empty() && neighbors_b.is_empty() {
   550→                    continue;
   551→                }
   552→
   553→                let intersection = neighbors_a.intersection(&neighbors_b).count();
   554→                let union = neighbors_a.union(&neighbors_b).count();
   555→
   556→                if union > 0 {
   557→                    let similarity = intersection as f32 / union as f32;
   558→                    if similarity > 0.3 {
   559→                        // Threshold for potential synonyms
   560→                        candidates.push((node_a.clone(), node_b.clone(), similarity));
   561→                    }
   562→                }
   563→            }
   564→        }
   565→
   566→        candidates.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
   567→        candidates
   568→    }
