   654→    /// Get test coverage report: which specifications have test links.
   655→    pub fn get_test_coverage(&self) -> TestCoverage {
   656→        let total_testable = self
   657→            .graph
   658→            .node_weights()
   659→            .filter(|n| matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario))
   660→            .count();
   661→
   662→        let with_tests = self
   663→            .graph
   664→            .node_weights()
   665→            .filter(|n| {
   666→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   667→                    && n.metadata.contains_key("test_file")
   668→            })
   669→            .count();
   670→
   671→        let nodes_with_tests: Vec<SpecNodeData> = self
   672→            .graph
   673→            .node_weights()
   674→            .filter(|n| {
   675→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   676→                    && n.metadata.contains_key("test_file")
   677→            })
   678→            .cloned()
   679→            .collect();
   680→
   681→        let nodes_without_tests: Vec<SpecNodeData> = self
   682→            .graph
   683→            .node_weights()
   684→            .filter(|n| {
   685→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   686→                    && !n.metadata.contains_key("test_file")
   687→            })
   688→            .cloned()
   689→            .collect();
   690→
   691→        TestCoverage {
   692→            total_testable,
   693→            with_tests,
   694→            coverage_ratio: if total_testable > 0 {
   695→                with_tests as f32 / total_testable as f32
   696→            } else {
   697→                0.0
   698→            },
   699→            nodes_with_tests,
   700→            nodes_without_tests,
   701→        }
   702→    }
