   704→    /// Calculate compliance score between a specification and code snippet.
   705→    /// Returns score 0.0-1.0 based on semantic similarity.
   706→    pub fn calculate_compliance(&self, node_id: &str, code: &str) -> Option<ComplianceScore> {
   707→        let node = self.get_node(node_id)?;
   708→
   709→        // Extract keywords from specification
   710→        let spec_keywords = self.extract_keywords(&node.content);
   711→        let code_keywords = self.extract_keywords(code);
   712→
   713→        if spec_keywords.is_empty() {
   714→            return Some(ComplianceScore {
   715→                score: 0.0,
   716→                keyword_overlap: 0.0,
   717→                structural_match: 0.0,
   718→                explanation: "Specification has no extractable keywords".to_string(),
   719→            });
   720→        }
   721→
   722→        // Calculate keyword overlap (Jaccard similarity)
   723→        let intersection = spec_keywords.intersection(&code_keywords).count();
   724→        let union = spec_keywords.union(&code_keywords).count();
   725→        let keyword_overlap = if union > 0 {
   726→            intersection as f32 / union as f32
   727→        } else {
   728→            0.0
   729→        };
   730→
   731→        // Structural matching for constraints/scenarios
   732→        let structural_match = match node.kind {
   733→            NodeKind::Constraint => self.match_constraint_structure(&node.content, code),
   734→            NodeKind::Scenario => self.match_scenario_structure(&node.content, code),
   735→            _ => 0.5, // Neutral for other types
   736→        };
   737→
   738→        // Weighted average (60% keywords, 40% structure)
   739→        let score = keyword_overlap * 0.6 + structural_match * 0.4;
   740→
   741→        let explanation = if score > 0.8 {
   742→            "Strong compliance - code closely matches specification".to_string()
   743→        } else if score > 0.5 {
   744→            "Moderate compliance - code partially matches specification".to_string()
   745→        } else if score > 0.2 {
   746→            "Weak compliance - code loosely relates to specification".to_string()
   747→        } else {
   748→            "Poor compliance - code does not match specification".to_string()
   749→        };
   750→
   751→        Some(ComplianceScore {
   752→            score,
   753→            keyword_overlap,
   754→            structural_match,
   755→            explanation,
   756→        })
   757→    }
   758→
   759→    fn extract_keywords(&self, text: &str) -> std::collections::HashSet<String> {
   760→        let stop_words = [
   761→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "is", "are",
   762→            "was", "were", "be", "been", "being", "have", "has", "had", "do", "does", "did",
   763→            "will", "would", "should", "could", "may", "might", "must", "can", "of", "by",
   764→            "with", "from", "as", "into", "through",
   765→        ];
   766→
   767→        text.to_lowercase()
   768→            .split_whitespace()
   769→            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()))
   770→            .filter(|w| w.len() > 2 && !stop_words.contains(w))
   771→            .map(|w| w.to_string())
   772→            .collect()
   773→    }
   774→
   775→    fn match_constraint_structure(&self, spec: &str, code: &str) -> f32 {
   776→        let spec_lower = spec.to_lowercase();
   777→        let code_lower = code.to_lowercase();
   778→
   779→        let mut score: f32 = 0.0;
   780→
   781→        // Look for constraint patterns
   782→        if (spec_lower.contains("must") || spec_lower.contains("should"))
   783→            && (code_lower.contains("assert")
   784→                || code_lower.contains("require")
   785→                || code_lower.contains("invariant"))
   786→        {
   787→            score += 0.3;
   788→        }
   789→
   790→        // Look for comparison operators
   791→        if (spec_lower.contains('>')
   792→            || spec_lower.contains('<')
   793→            || spec_lower.contains("greater")
   794→            || spec_lower.contains("less"))
   795→            && (code_lower.contains('>') || code_lower.contains('<'))
   796→        {
   797→            score += 0.2;
   798→        }
   799→
   800→        // Look for equality checks
   801→        if (spec_lower.contains("equal") || spec_lower.contains("same"))
   802→            && (code_lower.contains("==") || code_lower.contains("equals"))
   803→        {
   804→            score += 0.2;
   805→        }
   806→
   807→        // Look for boundary conditions
   808→        if (spec_lower.contains("not") || spec_lower.contains("never"))
   809→            && (code_lower.contains('!') || code_lower.contains("not"))
   810→        {
   811→            score += 0.3;
   812→        }
   813→
   814→        score.min(1.0)
   815→    }
   816→
   817→    fn match_scenario_structure(&self, spec: &str, code: &str) -> f32 {
   818→        let spec_lower = spec.to_lowercase();
   819→        let code_lower = code.to_lowercase();
   820→
   821→        let mut score: f32 = 0.0;
   822→
   823→        // Look for action words
   824→        let action_words = [
   825→            "login", "create", "update", "delete", "send", "receive", "verify",
   826→        ];
   827→        let has_action = action_words
   828→            .iter()
   829→            .any(|&w| spec_lower.contains(w) && code_lower.contains(w));
   830→        if has_action {
   831→            score += 0.4;
   832→        }
   833→
   834→        // Look for test structure
   835→        if code_lower.contains("test") || code_lower.contains("scenario") {
   836→            score += 0.2;
   837→        }
   838→
   839→        // Look for setup/action/verify pattern
   840→        let has_setup = code_lower.contains("setup") || code_lower.contains("given");
   841→        let has_action_code = code_lower.contains("when") || code_lower.contains("act");
   842→        let has_verify = code_lower.contains("assert")
   843→            || code_lower.contains("verify")
   844→            || code_lower.contains("expect");
   845→
   846→        if has_setup {
   847→            score += 0.1;
   848→        }
   849→        if has_action_code {
   850→            score += 0.15;
   851→        }
   852→        if has_verify {
   853→            score += 0.15;
   854→        }
   855→
   856→        score.min(1.0)
   857→    }
