   859→    /// Get compliance report for all specifications with linked code.
   860→    pub fn get_compliance_report(&self) -> Vec<(SpecNodeData, ComplianceScore)> {
   861→        self.graph
   862→            .node_weights()
   863→            .filter(|n| n.metadata.contains_key("impl_code") || n.metadata.contains_key("test_code"))
   864→            .filter_map(|n| {
   865→                let code = n
   866→                    .metadata
   867→                    .get("impl_code")
   868→                    .or_else(|| n.metadata.get("test_code"))?;
   869→                let score = self.calculate_compliance(&n.id, code)?;
   870→                Some((n.clone(), score))
   871→            })
   872→            .collect()
   873→    }
