   879→    /// Query graph state at a specific timestamp.
   880→    /// Returns nodes and edges that existed at that time.
   881→    pub fn query_at_timestamp(&self, timestamp: i64) -> TemporalSnapshot {
   882→        let nodes: Vec<SpecNodeData> = self
   883→            .graph
   884→            .node_weights()
   885→            .filter(|n| n.created_at <= timestamp)
   886→            .cloned()
   887→            .collect();
   888→
   889→        let edges: Vec<SpecEdgeData> = self
   890→            .graph
   891→            .edge_indices()
   892→            .filter_map(|eidx| {
   893→                let edge = &self.graph[eidx];
   894→                if edge.created_at <= timestamp {
   895→                    Some(edge.clone())
   896→                } else {
   897→                    None
   898→                }
   899→            })
   900→            .collect();
   901→
   902→        let node_count = nodes.len();
   903→        let edge_count = edges.len();
   904→
   905→        TemporalSnapshot {
   906→            timestamp,
   907→            nodes,
   908→            edges,
   909→            node_count,
   910→            edge_count,
   911→        }
   912→    }
   913→
   914→    /// Diff graph state between two timestamps.
   915→    /// Shows what was added, modified, or removed.
   916→    pub fn diff_timestamps(&self, from_timestamp: i64, to_timestamp: i64) -> TemporalDiff {
   917→        let from_snapshot = self.query_at_timestamp(from_timestamp);
   918→        let to_snapshot = self.query_at_timestamp(to_timestamp);
   919→
   920→        let from_node_ids: std::collections::HashSet<String> =
   921→            from_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   922→        let to_node_ids: std::collections::HashSet<String> =
   923→            to_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   924→
   925→        let added_nodes: Vec<SpecNodeData> = to_snapshot
   926→            .nodes
   927→            .iter()
   928→            .filter(|n| !from_node_ids.contains(&n.id))
   929→            .cloned()
   930→            .collect();
   931→
   932→        let removed_nodes: Vec<SpecNodeData> = from_snapshot
   933→            .nodes
   934→            .iter()
   935→            .filter(|n| !to_node_ids.contains(&n.id))
   936→            .cloned()
   937→            .collect();
   938→
   939→        let modified_nodes: Vec<(SpecNodeData, SpecNodeData)> = to_snapshot
   940→            .nodes
   941→            .iter()
   942→            .filter_map(|to_node| {
   943→                from_snapshot
   944→                    .nodes
   945→                    .iter()
   946→                    .find(|from_node| from_node.id == to_node.id)
   947→                    .and_then(|from_node| {
   948→                        if from_node.modified_at < to_node.modified_at {
   949→                            Some((from_node.clone(), to_node.clone()))
   950→                        } else {
   951→                            None
   952→                        }
   953→                    })
   954→            })
   955→            .collect();
   956→
   957→        let from_edge_ids: std::collections::HashSet<String> =
   958→            from_snapshot.edges.iter().map(|e| e.id.clone()).collect();
   959→        let to_edge_ids: std::collections::HashSet<String> =
   960→            to_snapshot.edges.iter().map(|e| e.id.clone()).collect();
   961→
   962→        let added_edges: Vec<SpecEdgeData> = to_snapshot
   963→            .edges
   964→            .iter()
   965→            .filter(|e| !from_edge_ids.contains(&e.id))
   966→            .cloned()
   967→            .collect();
   968→
   969→        let removed_edges: Vec<SpecEdgeData> = from_snapshot
   970→            .edges
   971→            .iter()
   972→            .filter(|e| !to_edge_ids.contains(&e.id))
   973→            .cloned()
   974→            .collect();
   975→
   976→        TemporalDiff {
   977→            from_timestamp,
   978→            to_timestamp,
   979→            added_nodes,
   980→            removed_nodes,
   981→            modified_nodes,
   982→            added_edges,
   983→            removed_edges,
   984→        }
   985→    }
