   987→    /// Get evolution history of a specific node.
   988→    /// Returns timeline of changes to the node.
   989→    pub fn get_node_history(&self, node_id: &str) -> Option<NodeHistory> {
   990→        let node = self.get_node(node_id)?;
   991→
   992→        let mut events = Vec::new();
   993→
   994→        // Creation event
   995→        events.push(HistoryEvent {
   996→            timestamp: node.created_at,
   997→            event_type: "created".to_string(),
   998→            description: format!("Node created: {}", node.content),
   999→        });
  1000→
  1001→        // Modification event (if modified after creation)
  1002→        if node.modified_at > node.created_at {
  1003→            events.push(HistoryEvent {
  1004→                timestamp: node.modified_at,
  1005→                event_type: "modified".to_string(),
  1006→                description: "Node content or metadata modified".to_string(),
  1007→            });
  1008→        }
  1009→
  1010→        // Edge creation events
  1011→        if let Some(&idx) = self.id_to_index.get(node_id) {
  1012→            for edge in self
  1013→                .graph
  1014→                .edges_directed(idx, Direction::Outgoing)
  1015→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
  1016→            {
  1017→                let edge_data = &self.graph[edge.id()];
  1018→                events.push(HistoryEvent {
  1019→                    timestamp: edge_data.created_at,
  1020→                    event_type: "edge_added".to_string(),
  1021→                    description: format!("Edge added: {:?}", edge_data.kind),
  1022→                });
  1023→            }
  1024→        }
  1025→
  1026→        // Sort events by timestamp
  1027→        events.sort_by_key(|e| e.timestamp);
  1028→
  1029→        Some(NodeHistory {
  1030→            node: node.clone(),
  1031→            events,
  1032→        })
  1033→    }
