  1035→    /// Track compliance trend over time for nodes with historical compliance data.
  1036→    /// Requires compliance scores stored in metadata with timestamps.
  1037→    pub fn get_compliance_trends(&self, node_id: &str) -> Option<ComplianceTrend> {
  1038→        let node = self.get_node(node_id)?;
  1039→
  1040→        // Extract compliance history from metadata (format: "compliance_<timestamp>")
  1041→        let mut data_points: Vec<ComplianceDataPoint> = node
  1042→            .metadata
  1043→            .iter()
  1044→            .filter_map(|(key, value)| {
  1045→                if key.starts_with("compliance_") {
  1046→                    let timestamp_str = key.strip_prefix("compliance_")?;
  1047→                    let timestamp: i64 = timestamp_str.parse().ok()?;
  1048→                    let score: f32 = value.parse().ok()?;
  1049→                    Some(ComplianceDataPoint { timestamp, score })
  1050→                } else {
  1051→                    None
  1052→                }
  1053→            })
  1054→            .collect();
  1055→
  1056→        if data_points.is_empty() {
  1057→            return None;
  1058→        }
  1059→
  1060→        // Sort by timestamp
  1061→        data_points.sort_by_key(|d| d.timestamp);
  1062→
  1063→        let trend_direction = if data_points.len() >= 2 {
  1064→            let first = data_points[0].score;
  1065→            let last = data_points[data_points.len() - 1].score;
  1066→            if last > first + 0.1 {
  1067→                "improving".to_string()
  1068→            } else if last < first - 0.1 {
  1069→                "degrading".to_string()
  1070→            } else {
  1071→                "stable".to_string()
  1072→            }
  1073→        } else {
  1074→            "unknown".to_string()
  1075→        };
  1076→
  1077→        Some(ComplianceTrend {
  1078→            node: node.clone(),
  1079→            data_points,
  1080→            trend_direction,
  1081→        })
  1082→    }
