  1088→    /// Export the specification graph in DOT format (Graphviz).
  1089→    /// Nodes are colored by formality layer (U0=blue, U1=green, U2=yellow, U3=red).
  1090→    /// Edges are styled by kind (Refines, Formalizes, etc.).
  1091→    pub fn export_dot(&self) -> String {
  1092→        let mut dot = String::from("digraph spec_oracle {\n");
  1093→        dot.push_str("    rankdir=LR;\n");
  1094→        dot.push_str("    node [shape=box, style=filled];\n");
  1095→        dot.push_str("    edge [fontsize=10];\n\n");
  1096→
  1097→        // Helper function to escape DOT strings
  1098→        fn escape_dot(s: &str) -> String {
  1099→            s.replace('\\', "\\\\")
  1100→                .replace('"', "\\\"")
  1101→                .replace('\n', "\\n")
  1102→        }
  1103→
  1104→        // Helper function to truncate content
  1105→        fn truncate(s: &str, max_len: usize) -> String {
  1106→            if s.len() > max_len {
  1107→                format!("{}...", &s[..max_len])
  1108→            } else {
  1109→                s.to_string()
  1110→            }
  1111→        }
  1112→
  1113→        // Helper function to get layer color
  1114→        fn layer_color(layer: u8) -> &'static str {
  1115→            match layer {
  1116→                0 => "lightblue",   // U0: natural language
  1117→                1 => "lightgreen",  // U1: structured/formal
  1118→                2 => "lightyellow", // U2: interface/API
  1119→                3 => "lightcoral",  // U3: implementation
  1120→                _ => "white",
  1121→            }
  1122→        }
  1123→
  1124→        // Helper function to get layer label
  1125→        fn layer_label(layer: u8) -> &'static str {
  1126→            match layer {
  1127→                0 => "U0",
  1128→                1 => "U1",
  1129→                2 => "U2",
  1130→                3 => "U3",
  1131→                _ => "U?",
  1132→            }
  1133→        }
  1134→
  1135→        // Helper function to get kind abbreviation
  1136→        fn kind_abbr(kind: NodeKind) -> &'static str {
  1137→            match kind {
  1138→                NodeKind::Assertion => "A",
  1139→                NodeKind::Constraint => "C",
  1140→                NodeKind::Scenario => "S",
  1141→                NodeKind::Definition => "D",
  1142→                NodeKind::Domain => "Dom",
  1143→            }
  1144→        }
  1145→
  1146→        // Add nodes
  1147→        for node in self.graph.node_weights() {
  1148→            let layer = node.formality_layer;
  1149→            let color = layer_color(layer);
  1150→            let layer_lbl = layer_label(layer);
  1151→            let kind_lbl = kind_abbr(node.kind);
  1152→            let content_short = truncate(&node.content, 50);
  1153→            let label = format!("[{}] {} {}", layer_lbl, kind_lbl, content_short);
  1154→
  1155→            dot.push_str(&format!(
  1156→                "    \"{}\" [label=\"{}\", fillcolor=\"{}\"];\n",
  1157→                escape_dot(&node.id),
  1158→                escape_dot(&label),
  1159→                color
  1160→            ));
  1161→        }
  1162→
  1163→        dot.push('\n');
  1164→
  1165→        // Add edges
  1166→        for edge_idx in self.graph.edge_indices() {
  1167→            if let Some((source_idx, target_idx)) = self.graph.edge_endpoints(edge_idx) {
  1168→                if let Some(edge) = self.graph.edge_weight(edge_idx) {
  1169→                    if let (Some(source_node), Some(target_node)) = (
  1170→                        self.graph.node_weight(source_idx),
  1171→                        self.graph.node_weight(target_idx),
  1172→                    ) {
  1173→                        let edge_style = match edge.kind {
  1174→                            EdgeKind::Refines => "solid",
  1175→                            EdgeKind::Formalizes => "bold",
  1176→                            EdgeKind::DerivesFrom => "dashed",
  1177→                            EdgeKind::Transform => "dotted",
  1178→                            EdgeKind::Contradicts => "bold, color=red",
  1179→                            EdgeKind::DependsOn => "dashed",
  1180→                            EdgeKind::Synonym => "dotted, color=gray",
  1181→                            EdgeKind::Composes => "solid",
  1182→                        };
  1183→
  1184→                        let edge_label = format!("{:?}", edge.kind);
  1185→
  1186→                        dot.push_str(&format!(
  1187→                            "    \"{}\" -> \"{}\" [label=\"{}\", style=\"{}\"];\n",
  1188→                            escape_dot(&source_node.id),
  1189→                            escape_dot(&target_node.id),
  1190→                            edge_label,
  1191→                            edge_style
  1192→                        ));
  1193→                    }
  1194→                }
  1195→            }
  1196→        }
  1197→
  1198→        dot.push_str("}\n");
  1199→        dot
  1200→    }
  1201→}
