     1→/// UDAF Model: The complete multi-universe specification model
     2→///
     3→/// This is the core data structure that implements the theoretical foundation
     4→/// of specORACLE as described in conversation.md and motivation.md.
     5→
     6→use serde::{Deserialize, Serialize};
     7→use std::collections::{HashMap, HashSet};
     8→use crate::formal::*;
     9→use crate::{SpecGraph, InferredSpecification, RustExtractor};
    10→
    11→#[derive(Debug, Clone, Serialize, Deserialize)]
    12→pub struct UDAFModel {
    13→    /// All universes in the model (keyed by UniverseId)
    14→    #[serde(with = "super::serde_helpers::universe_map_serde")]
    15→    pub universes: HashMap<UniverseId, Universe>,
    16→
    17→    /// All domains across all universes (keyed by DomainId)
    18→    #[serde(with = "super::serde_helpers::domain_map_serde")]
    19→    pub domains: HashMap<DomainId, Domain>,
    20→
    21→    /// All admissible sets (one per specification, keyed by SpecId)
    22→    #[serde(with = "super::serde_helpers::admissible_map_serde")]
    23→    pub admissible_sets: HashMap<SpecId, AdmissibleSet>,
    24→
    25→    /// All transform functions between universes (keyed by TransformId)
    26→    #[serde(with = "super::serde_helpers::transform_map_serde")]
    27→    pub transforms: HashMap<TransformId, TransformFunction>,
    28→
    29→    /// Metadata for extensibility
    30→    pub metadata: Metadata,
    31→
    32→    /// Prover instance for formal verification (not serialized)
    33→    #[serde(skip)]
    34→    #[cfg(feature = "z3-solver")]
    35→    prover: Prover,
    36→}
    37→
    38→impl UDAFModel {
    39→    pub fn new() -> Self {
    40→        let mut model = Self {
    41→            universes: HashMap::new(),
    42→            domains: HashMap::new(),
    43→            admissible_sets: HashMap::new(),
    44→            transforms: HashMap::new(),
    45→            metadata: Metadata::new(),
    46→            #[cfg(feature = "z3-solver")]
    47→            prover: Prover::new(),
    48→        };
    49→
    50→        // Always create U0 (root universe)
    51→        let u0 = Universe::root();
    52→        model.universes.insert(u0.id.clone(), u0);
    53→
    54→        model
    55→    }
    56→
    57→    /// Add a projection universe (U1, U2, etc.)
    58→    ///
    59→    /// Returns the universe ID or an error if layer is invalid
    60→    pub fn add_universe(&mut self, layer: u8, name: String, description: String) -> Result<UniverseId, IdError> {
    61→        let universe = Universe::projection(layer, name, description)?;
    62→        let id = universe.id.clone();
    63→        self.universes.insert(id.clone(), universe);
    64→        Ok(id)
    65→    }
    66→
    67→    /// Add a domain to a universe
    68→    pub fn add_domain(&mut self, domain: Domain) -> DomainId {
    69→        let id = domain.id.clone();
    70→        self.domains.insert(id.clone(), domain);
    71→        id
    72→    }
    73→
    74→    /// Add an admissible set for a specification
    75→    pub fn add_admissible_set(&mut self, admissible_set: AdmissibleSet) -> SpecId {
    76→        let id = admissible_set.spec_id.clone();
    77→        self.admissible_sets.insert(id.clone(), admissible_set);
    78→        id
