   498→    /// Validate all reference integrity across the model
   499→    ///
   500→    /// Checks:
   501→    /// - Universe specifications reference valid SpecIds
   502→    /// - Domain universe_id references valid UniverseIds
   503→    /// - Domain covered_by references valid SpecIds
   504→    /// - Domain subdomains references valid DomainIds
   505→    /// - AdmissibleSet universe_id references valid UniverseIds
   506→    /// - AdmissibleSet contradicts references valid SpecIds
   507→    /// - Transform source/target universes reference valid UniverseIds
   508→    ///
   509→    /// Returns Ok(()) if all references are valid, or Err with details of invalid references
   510→    pub fn validate(&self) -> Result<(), String> {
   511→        let mut errors = Vec::new();
   512→
   513→        // Collect all valid IDs for reference checking
   514→        let valid_universe_ids: HashSet<String> = self.universes.keys()
   515→            .map(|id| id.as_str().to_string())
   516→            .collect();
   517→
   518→        let valid_spec_ids: HashSet<String> = self.admissible_sets.keys()
   519→            .map(|id| id.as_str().to_string())
   520→            .collect();
   521→
   522→        let valid_domain_ids: HashSet<String> = self.domains.keys()
   523→            .map(|id| id.as_str().to_string())
   524→            .collect();
   525→
   526→        // Validate Universe references
   527→        for (universe_id, universe) in &self.universes {
   528→            // Check that all specifications in the universe exist
   529→            let invalid_specs = universe.specifications.check_integrity(&valid_spec_ids);
   530→            if !invalid_specs.is_empty() {
   531→                errors.push(format!(
   532→                    "Universe {} references non-existent specifications: {:?}",
   533→                    universe_id.as_str(),
   534→                    invalid_specs
   535→                ));
   536→            }
   537→        }
   538→
   539→        // Validate Domain references
   540→        for (domain_id, domain) in &self.domains {
   541→            // Check that universe_id exists (try meta first, fall back to old field)
   542→            let universe_id_str = if let Some(meta) = &domain.meta {
   543→                meta.get_str("universe_id").map(|s| s.as_str())
   544→            } else {
   545→                domain.universe_id.as_ref().map(|id| id.as_str())
   546→            };
   547→
   548→            if let Some(uid_str) = universe_id_str {
   549→                if !valid_universe_ids.contains(uid_str) {
   550→                    errors.push(format!(
   551→                        "Domain {} references non-existent universe: {}",
   552→                        domain_id.as_str(),
   553→                        uid_str
   554→                    ));
   555→                }
   556→            }
   557→
   558→            // Check that all covered_by specs exist (try proof_data first, fall back to old field)
   559→            let covered_by = if let Some(proof_data) = &domain.proof_data {
   560→                Some(&proof_data.covered_by)
   561→            } else {
   562→                domain.covered_by.as_ref()
   563→            };
   564→
   565→            if let Some(covered_by_set) = covered_by {
   566→                let invalid_specs = covered_by_set.check_integrity(&valid_spec_ids);
   567→                if !invalid_specs.is_empty() {
   568→                    errors.push(format!(
   569→                        "Domain {} references non-existent specifications in covered_by: {:?}",
   570→                        domain_id.as_str(),
   571→                        invalid_specs
   572→                    ));
   573→                }
   574→            }
   575→
   576→            // Check that all subdomains exist (from meta)
   577→            if let Some(meta) = &domain.meta {
   578→                if let Some(_subdomains_str) = meta.get_str("subdomains") {
   579→                    // Note: This is a simplified check; actual subdomain validation would need proper parsing
   580→                    // For now, skip subdomain validation for new structure
   581→                }
   582→            } else if let Some(subdomains) = &domain.subdomains {
   583→                let invalid_domains = subdomains.check_integrity(&valid_domain_ids);
   584→                if !invalid_domains.is_empty() {
   585→                    errors.push(format!(
   586→                        "Domain {} references non-existent subdomains: {:?}",
   587→                        domain_id.as_str(),
   588→                        invalid_domains
   589→                    ));
   590→                }
   591→            }
   592→        }
   593→
   594→        // Validate AdmissibleSet references
   595→        for (spec_id, admissible_set) in &self.admissible_sets {
   596→            // Check that universe_id exists (try meta first, fall back to old field)
   597→            let universe_id_ref = if let Some(meta) = &admissible_set.meta {
   598→                Some(&meta.universe_id)
   599→            } else {
   600→                admissible_set.universe_id.as_ref()
   601→            };
   602→
   603→            if let Some(uid) = universe_id_ref {
   604→                if !valid_universe_ids.contains(uid.as_str()) {
   605→                    errors.push(format!(
   606→                        "AdmissibleSet {} references non-existent universe: {}",
   607→                        spec_id.as_str(),
   608→                        uid.as_str()
   609→                    ));
   610→                }
   611→            }
   612→
   613→            // Check that all contradicts references exist (try proof_data first, fall back to old field)
   614→            let contradicts = if let Some(proof_data) = &admissible_set.proof_data {
   615→                Some(&proof_data.contradicts)
   616→            } else {
   617→                admissible_set.contradicts.as_ref()
   618→            };
   619→
   620→            if let Some(contradicts_set) = contradicts {
   621→                let invalid_contradicts = contradicts_set.check_integrity(&valid_spec_ids);
   622→                if !invalid_contradicts.is_empty() {
   623→                    errors.push(format!(
   624→                        "AdmissibleSet {} references non-existent specifications in contradicts: {:?}",
   625→                        spec_id.as_str(),
   626→                        invalid_contradicts
   627→                    ));
   628→                }
   629→            }
   630→        }
   631→
   632→        // Validate Transform references
   633→        for (transform_id, transform) in &self.transforms {
   634→            // Check that source_universe exists
   635→            if !valid_universe_ids.contains(transform.source_universe.as_str()) {
   636→                errors.push(format!(
   637→                    "Transform {} references non-existent source universe: {}",
   638→                    transform_id.as_str(),
   639→                    transform.source_universe.as_str()
   640→                ));
   641→            }
   642→
   643→            // Check that target_universe exists
   644→            if !valid_universe_ids.contains(transform.target_universe.as_str()) {
   645→                errors.push(format!(
   646→                    "Transform {} references non-existent target universe: {}",
   647→                    transform_id.as_str(),
   648→                    transform.target_universe.as_str()
   649→                ));
   650→            }
   651→        }
   652→
   653→        if errors.is_empty() {
   654→            Ok(())
   655→        } else {
   656→            Err(errors.join("\n"))
   657→        }
   658→    }
   659→}
