     9→/// Extract constraints from natural language text
    10→///
    11→/// Parses specification text to identify implicit constraints like:
    12→/// - "at least N" → minimum constraint
    13→/// - "at most N" → maximum constraint
    14→/// - "must be" / "must not be" → boolean constraints
    15→/// - "between X and Y" → range constraints
    16→///
    17→/// This is the consolidated implementation that replaces duplicates in
    18→/// graph.rs and model.rs.
    19→pub fn extract_constraints_from_text(text: &str) -> Vec<Constraint> {
    20→    let mut constraints = Vec::new();
    21→    let lower_text = text.to_lowercase();
    22→
    23→    // Pattern 1: "at least N"
    24→    if let Some(min_value) = extract_numeric_value(&lower_text, "at least") {
    25→        let mut meta = ConstraintMetadata::new();
    26→        meta.set_pattern("at_least".to_string());
    27→        meta.set_value(min_value.to_string());
    28→        meta.set_source(text.to_string());
    29→
    30→        // Context-aware variable extraction
    31→        let variable = extract_variable_context(&lower_text, "at least");
    32→        if let Some(var) = &variable {
    33→            meta.insert(MetadataKey::Custom("variable".to_string()), var.clone());
    34→        }
    35→
    36→        let description_text = if let Some(var) = variable {
    37→            format!("{} must be at least {}", var, min_value)
    38→        } else {
    39→            format!("Minimum value: {}", min_value)
    40→        };
    41→
    42→        let mut meta_with_desc = meta.clone();
    43→        meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
    44→
    45→        let formal = if let Some(var) = extract_variable_context(&lower_text, "at least") {
    46→            format!("(>= {} {})", var, min_value)
    47→        } else {
    48→            format!(">= {}", min_value)
    49→        };
    50→
    51→        constraints.push(Constraint {
    52→            formal: Some(formal),
    53→            kind: ConstraintKind::Universal,
    54→            description: Some(description_text),
    55→            metadata: Some(meta),
    56→            meta: Some(meta_with_desc),
    57→        });
    58→    }
    59→
    60→    // Pattern 2: "at most N"
    61→    if let Some(max_value) = extract_numeric_value(&lower_text, "at most") {
    62→        let mut meta = ConstraintMetadata::new();
    63→        meta.set_pattern("at_most".to_string());
    64→        meta.set_value(max_value.to_string());
    65→        meta.set_source(text.to_string());
    66→
    67→        let variable = extract_variable_context(&lower_text, "at most");
