            NodeKind::Constraint,
            metadata.clone(),
        );
        repo.update_node_formality(&node1.id, 1);

        let node2 = repo.add_node(
            "U2 spec".to_string(),
            NodeKind::Scenario,
            metadata.clone(),
        );
        repo.update_node_formality(&node2.id, 2);

        let mut model = UDAFModel::new();
