   402→    println!("🔬 Proving Implication Between Specifications\n");
   403→    println!("═══════════════════════════════════════════════════════════════\n");
   404→
   405→    // Get the specifications
   406→    let node_a = graph.get_node(&antecedent_id);
   407→    let node_b = graph.get_node(&consequent_id);
   408→
   409→    if node_a.is_none() {
   410→        eprintln!("❌ Specification (antecedent) '{}' not found", antecedent_id);
   411→        std::process::exit(1);
   412→    }
   413→    if node_b.is_none() {
   414→        eprintln!("❌ Specification (consequent) '{}' not found", consequent_id);
   415→        std::process::exit(1);
   416→    }
   417→
   418→    let node_a = node_a.unwrap();
   419→    let node_b = node_b.unwrap();
   420→
   421→    println!("📋 Antecedent (A1):");
   422→    println!("   ID:      [{}]", &antecedent_id[..8]);
   423→    println!("   Content: {}", node_a.content);
   424→    println!("   Kind:    {:?}", node_a.kind);
   425→    println!();
   426→
   427→    println!("📋 Consequent (A2):");
   428→    println!("   ID:      [{}]", &consequent_id[..8]);
   429→    println!("   Content: {}", node_b.content);
   430→    println!("   Kind:    {:?}", node_b.kind);
   431→    println!();
   432→
   433→    // Get admissible sets
   434→    let admissible_a = udaf_model.admissible_sets.get(&antecedent_id);
   435→    let admissible_b = udaf_model.admissible_sets.get(&consequent_id);
   436→
   437→    if admissible_a.is_none() || admissible_b.is_none() {
   438→        println!("⚠️  Admissible sets not found in U/D/A/f model");
   439→        println!("   Run 'spec inspect-model' to verify model state");
   440→        std::process::exit(1);
   441→    }
   442→
   443→    let admissible_a = admissible_a.unwrap();
   444→    let admissible_b = admissible_b.unwrap();
   445→
   446→    // Extract constraints (handle both old and new structure)
   447→    let constraints_a = if let Some(ref proof_data) = admissible_a.proof_data {
   448→        &proof_data.constraints
   449→    } else if let Some(ref constraints) = admissible_a.constraints {
   450→        constraints
   451→    } else {
   452→        eprintln!("❌ No constraints found in antecedent admissible set");
   453→        std::process::exit(1);
   454→    };
   455→
   456→    let constraints_b = if let Some(ref proof_data) = admissible_b.proof_data {
   457→        &proof_data.constraints
   458→    } else if let Some(ref constraints) = admissible_b.constraints {
   459→        constraints
   460→    } else {
   461→        eprintln!("❌ No constraints found in consequent admissible set");
   462→        std::process::exit(1);
   463→    };
   464→
   465→    println!("🔍 Antecedent Constraints: {}", constraints_a.len());
   466→    for (i, constraint) in constraints_a.iter().enumerate() {
   467→        let desc = if let Some(ref meta) = constraint.meta {
   468→            meta.get_str("description").map(|s| s.as_str())
   469→        } else {
   470→            constraint.description.as_deref()
   471→        }.unwrap_or("(no description)");
   472→        println!("   {}: {} ({:?})", i+1, desc, constraint.kind);
   473→    }
   474→    println!();
   475→
   476→    println!("🔍 Consequent Constraints: {}", constraints_b.len());
   477→    for (i, constraint) in constraints_b.iter().enumerate() {
   478→        let desc = if let Some(ref meta) = constraint.meta {
   479→            meta.get_str("description").map(|s| s.as_str())
   480→        } else {
   481→            constraint.description.as_deref()
   482→        }.unwrap_or("(no description)");
   483→        println!("   {}: {} ({:?})", i+1, desc, constraint.kind);
   484→    }
   485→    println!();
   486→
   487→    // Prove implication
   488→    let mut prover = Prover::new();
   489→    let proof = prover.prove_implication(admissible_a, admissible_b);
   490→
   491→    println!("═══════════════════════════════════════════════════════════════\n");
   492→    println!("📜 Formal Proof Generated\n");
   493→    println!("Property: {:?}", proof.property);
   494→    println!("Method:   {:?}", proof.method);
   495→    println!("Status:   {:?}", proof.status);
   496→    println!();
   497→
   498→    println!("Proof Steps:");
   499→    for (i, step) in proof.steps.iter().enumerate() {
   500→        println!("  {}. {}", i+1, step.description);
   501→        println!("     Justification: {}", step.justification);
   502→        println!();
   503→    }
   504→
   505→    match proof.status {
   506→        ProofStatus::Proven => {
   507→            println!("✅ PROVEN: A1 ⊆ A2 (Implication holds)");
   508→            println!("   Every implementation satisfying A1 also satisfies A2");
