/// DetectContradictions command: Formal verification of specification consistency
///
/// Uses UDAFModel for formal verification of consistency between specifications.

use crate::proto;
use spec_core::{Store, SpecRepository, UDAFModel, ModelSync};
use tonic::Request;

/// Execute DetectContradictions in standalone mode
pub fn execute_contradictions_standalone(
    store: &Store,
) -> Result<(), Box<dyn std::error::Error>> {
    // Load from store and convert to repository
    let spec_graph = store.load()?;
    let mut repo = SpecRepository::from_spec_graph(&spec_graph);

    // Sync to UDAFModel
    let mut udaf_model = UDAFModel::new();
    ModelSync::sync_from_repository(&mut udaf_model, &repo)?;

    println!("🔍 Detecting Contradictions (Formal Verification)\n");
    println!("═══════════════════════════════════════════════════════════════\n");

    // Get all nodes to check pairwise
    let nodes = repo.list_nodes(None);
    let mut contradictions_found = 0;
    let mut checked_pairs = 0;

    println!("Analyzing {} specifications...\n", nodes.len());

    // Use UDAFModel's detect_contradictions method
    let contradictions = udaf_model.detect_contradictions();

    // Display contradictions found by UDAFModel
    for contradiction in &contradictions {
        contradictions_found += 1;

        // Get node details from repository
        if let (Some(node_a), Some(node_b)) = (
            repo.get_node(&contradiction.spec_a_id),
            repo.get_node(&contradiction.spec_b_id),
        ) {
            println!("❌ Contradiction #{}\n", contradictions_found);
            println!("   Specification A:");
            println!("     ID:      [{}]", &node_a.id[..8]);
            println!("     Content: {}", node_a.content);
            println!();

            println!("   Specification B:");
            println!("     ID:      [{}]", &node_b.id[..8]);
            println!("     Content: {}", node_b.content);
            println!();

            println!("   Reason: {}", contradiction.reason);
            println!();

            println!("   Mathematical Result:");
            println!("     A₁ ∩ A₂ = ∅ (admissible sets are disjoint)");
            println!("     No implementation can satisfy both specifications");
            println!("\n   ───────────────────────────────────────────────────────────\n");
        }
    }

    // Export proof metadata back to repository
    ModelSync::export_proof_metadata(&udaf_model, &mut repo)?;

    // Note: Saving back to store would require converting SpecRepository → SpecGraph
    // For now, proof metadata is in-memory only
    // TODO: Implement SpecRepository → SpecGraph conversion for saving

    println!("═══════════════════════════════════════════════════════════════\n");
    println!("Summary:");
    println!("  Specifications checked: {}", nodes.len());
    println!("  Pairwise comparisons: {}", checked_pairs);
    println!("  Contradictions found: {}", contradictions_found);
    println!();

