     1→/// SpecRepository: Pure data persistence layer for specification graph
     2→///
     3→/// This module contains ALL pure data operations:
     4→/// - CRUD on nodes and edges
     5→/// - Graph traversal and queries
     6→/// - Search and filtering
     7→/// - Test coverage and compliance calculation
     8→/// - Temporal queries (versioning, history, diff)
     9→/// - Serialization (JSON, DOT)
    10→///
    11→/// ARCHITECTURAL CONSTRAINT:
    12→/// NO imports from crate::formal:: module allowed here.
    13→/// This is pure data layer - formal verification belongs in UDAFModel.
    14→
    15→use chrono::Utc;
    16→use petgraph::graph::{DiGraph, EdgeIndex, NodeIndex};
    17→use petgraph::visit::EdgeRef;
    18→use petgraph::Direction;
    19→use serde::{Deserialize, Serialize};
    20→use std::collections::HashMap;
    21→use uuid::Uuid;
    22→
    23→use super::*; // Import data module types
    24→use crate::SpecGraph; // For conversion from legacy format
    25→
    26→/// Pure data repository for specification graph
    27→#[derive(Debug, Clone, Serialize, Deserialize)]
    28→pub struct SpecRepository {
    29→    graph: DiGraph<SpecNodeData, SpecEdgeData>,
    30→    #[serde(skip)]
    31→    id_to_index: HashMap<String, NodeIndex>,
    32→    #[serde(skip)]
    33→    edge_id_to_index: HashMap<String, EdgeIndex>,
    34→}
    35→
    36→impl Default for SpecRepository {
    37→    fn default() -> Self {
    38→        Self::new()
    39→    }
    40→}
    41→
    42→impl SpecRepository {
    43→    pub fn new() -> Self {
    44→        Self {
    45→            graph: DiGraph::new(),
    46→            id_to_index: HashMap::new(),
    47→            edge_id_to_index: HashMap::new(),
    48→        }
    49→    }
    50→
    51→    /// Rebuild lookup indices after deserialization.
    52→    pub fn rebuild_indices(&mut self) {
    53→        self.id_to_index.clear();
    54→        self.edge_id_to_index.clear();
    55→        for idx in self.graph.node_indices() {
    56→            let node = &self.graph[idx];
    57→            self.id_to_index.insert(node.id.clone(), idx);
    58→        }
    59→        for idx in self.graph.edge_indices() {
    60→            let edge = &self.graph[idx];
    61→            self.edge_id_to_index.insert(edge.id.clone(), idx);
    62→        }
    63→    }
    64→
    65→    /// Convert from legacy SpecGraph to SpecRepository
    66→    pub fn from_spec_graph(spec_graph: &crate::SpecGraph) -> Self {
    67→        let mut repo = Self::new();
    68→
    69→        // Add all nodes - convert from graph::SpecNodeData to data::SpecNodeData
    70→        for node in spec_graph.list_nodes(None) {
    71→            let data_node = SpecNodeData {
    72→                id: node.id.clone(),
    73→                content: node.content.clone(),
    74→                kind: match node.kind {
    75→                    crate::NodeKind::Assertion => NodeKind::Assertion,
    76→                    crate::NodeKind::Constraint => NodeKind::Constraint,
    77→                    crate::NodeKind::Scenario => NodeKind::Scenario,
    78→                    crate::NodeKind::Definition => NodeKind::Definition,
    79→                    crate::NodeKind::Domain => NodeKind::Domain,
    80→                },
    81→                metadata: node.metadata.clone(),
    82→                created_at: node.created_at,
    83→                modified_at: node.modified_at,
    84→                formality_layer: node.formality_layer,
    85→            };
    86→            repo.add_node_from_loaded(data_node);
    87→        }
    88→
    89→        // Add all edges - convert from graph::EdgeKind to data::EdgeKind
    90→        for (edge_data, source_id, target_id) in spec_graph.list_edges(None) {
    91→            let kind = match edge_data.kind {
    92→                crate::EdgeKind::Formalizes => EdgeKind::Formalizes,
    93→                crate::EdgeKind::Transform => EdgeKind::Transform,
    94→                crate::EdgeKind::Refines => EdgeKind::Refines,
    95→                crate::EdgeKind::DerivesFrom => EdgeKind::DerivesFrom,
    96→                crate::EdgeKind::DependsOn => EdgeKind::DependsOn,
    97→                crate::EdgeKind::Contradicts => EdgeKind::Contradicts,
    98→                crate::EdgeKind::Synonym => EdgeKind::Synonym,
    99→                crate::EdgeKind::Composes => EdgeKind::Composes,
   100→            };
   101→            // Add edge using source and target IDs
   102→            let _ = repo.add_edge(source_id, target_id, kind, edge_data.metadata.clone());
   103→        }
   104→
   105→        repo
   106→    }
   107→
   108→    // ========================================================================
   109→    // Node operations
   110→    // ========================================================================
   111→
   112→    pub fn add_node(
   113→        &mut self,
   114→        content: String,
   115→        kind: NodeKind,
   116→        metadata: HashMap<String, String>,
   117→    ) -> &SpecNodeData {
   118→        let id = Uuid::new_v4().to_string();
   119→        let now = Utc::now().timestamp();
   120→        let data = SpecNodeData {
   121→            id: id.clone(),
   122→            content,
   123→            kind,
   124→            metadata,
   125→            created_at: now,
   126→            modified_at: now,
   127→            formality_layer: 0, // Default to natural language
   128→        };
   129→        let idx = self.graph.add_node(data);
   130→        self.id_to_index.insert(id, idx);
   131→        &self.graph[idx]
   132→    }
   133→
   134→    /// Add a node from loaded data (preserves existing ID and timestamps)
   135→    pub fn add_node_from_loaded(&mut self, node: SpecNodeData) -> String {
   136→        let id = node.id.clone();
   137→        let idx = self.graph.add_node(node);
   138→        self.id_to_index.insert(id.clone(), idx);
   139→        id
   140→    }
   141→
   142→    pub fn get_node(&self, id: &str) -> Option<&SpecNodeData> {
   143→        self.id_to_index.get(id).map(|&idx| &self.graph[idx])
   144→    }
   145→
   146→    /// Find a node by content and kind (for deduplication)
   147→    pub fn find_node_by_content(&self, content: &str, kind: NodeKind) -> Option<&SpecNodeData> {
   148→        self.graph
   149→            .node_weights()
   150→            .find(|n| n.content == content && n.kind == kind)
   151→    }
   152→
   153→    pub fn update_node_formality(&mut self, id: &str, formality_layer: u8) -> bool {
   154→        if let Some(&idx) = self.id_to_index.get(id) {
   155→            if let Some(node) = self.graph.node_weight_mut(idx) {
   156→                node.formality_layer = formality_layer;
   157→                node.modified_at = Utc::now().timestamp();
   158→                return true;
   159→            }
   160→        }
   161→        false
   162→    }
   163→
   164→    pub fn update_node_metadata(
   165→        &mut self,
   166→        id: &str,
   167→        key: String,
   168→        value: String,
   169→    ) -> Option<SpecNodeData> {
   170→        if let Some(&idx) = self.id_to_index.get(id) {
   171→            if let Some(node) = self.graph.node_weight_mut(idx) {
   172→                node.metadata.insert(key, value);
   173→                node.modified_at = Utc::now().timestamp();
   174→                return Some(node.clone());
   175→            }
   176→        }
   177→        None
   178→    }
   179→
   180→    pub fn remove_node(&mut self, id: &str) -> Option<SpecNodeData> {
   181→        if let Some(&idx) = self.id_to_index.get(id) {
   182→            // Remove related edge index entries
   183→            let edge_indices: Vec<EdgeIndex> = self
   184→                .graph
   185→                .edges_directed(idx, Direction::Outgoing)
   186→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
   187→                .map(|e| e.id())
   188→                .collect();
   189→            for eidx in edge_indices {
   190→                if let Some(edge_data) = self.graph.edge_weight(eidx) {
   191→                    self.edge_id_to_index.remove(&edge_data.id);
   192→                }
   193→            }
   194→
   195→            let data = self.graph.remove_node(idx)?;
   196→            self.id_to_index.remove(&data.id);
   197→
   198→            // After removal petgraph may swap indices; rebuild to stay consistent.
   199→            self.rebuild_indices();
   200→            Some(data)
   201→        } else {
   202→            None
   203→        }
   204→    }
   205→
   206→    pub fn list_nodes(&self, kind_filter: Option<NodeKind>) -> Vec<&SpecNodeData> {
   207→        self.graph
   208→            .node_weights()
   209→            .filter(|n| kind_filter.is_none() || Some(n.kind) == kind_filter)
   210→            .collect()
   211→    }
