   213→    // ========================================================================
   214→    // Edge operations
   215→    // ========================================================================
   216→
   217→    pub fn add_edge(
   218→        &mut self,
   219→        source_id: &str,
   220→        target_id: &str,
   221→        kind: EdgeKind,
   222→        metadata: HashMap<String, String>,
   223→    ) -> Result<&SpecEdgeData, GraphError> {
   224→        let &src_idx = self
   225→            .id_to_index
   226→            .get(source_id)
   227→            .ok_or_else(|| GraphError::NodeNotFound(source_id.to_string()))?;
   228→        let &tgt_idx = self
   229→            .id_to_index
   230→            .get(target_id)
   231→            .ok_or_else(|| GraphError::NodeNotFound(target_id.to_string()))?;
   232→
   233→        let id = Uuid::new_v4().to_string();
   234→        let now = Utc::now().timestamp();
   235→        let data = SpecEdgeData {
   236→            id: id.clone(),
   237→            kind,
   238→            metadata,
   239→            created_at: now,
   240→        };
   241→        let eidx = self.graph.add_edge(src_idx, tgt_idx, data);
   242→        self.edge_id_to_index.insert(id, eidx);
   243→        Ok(&self.graph[eidx])
   244→    }
   245→
   246→    /// Add an edge from loaded data (preserves existing ID and timestamps)
   247→    pub fn add_edge_from_loaded(&mut self, edge: Edge) -> Result<String, GraphError> {
   248→        let &src_idx = self
   249→            .id_to_index
   250→            .get(&edge.source)
   251→            .ok_or_else(|| GraphError::NodeNotFound(edge.source.clone()))?;
   252→        let &tgt_idx = self
   253→            .id_to_index
   254→            .get(&edge.target)
   255→            .ok_or_else(|| GraphError::NodeNotFound(edge.target.clone()))?;
   256→
   257→        let id = edge.data.id.clone();
   258→        let eidx = self.graph.add_edge(src_idx, tgt_idx, edge.data);
   259→        self.edge_id_to_index.insert(id.clone(), eidx);
   260→        Ok(id)
   261→    }
   262→
   263→    pub fn remove_edge(&mut self, id: &str) -> Option<SpecEdgeData> {
   264→        if let Some(&eidx) = self.edge_id_to_index.get(id) {
   265→            let data = self.graph.remove_edge(eidx)?;
   266→            self.edge_id_to_index.remove(&data.id);
   267→            // Edge removal can invalidate other edge indices; rebuild.
   268→            self.rebuild_indices();
   269→            Some(data)
   270→        } else {
   271→            None
   272→        }
   273→    }
   274→
   275→    pub fn list_edges(&self, node_id: Option<&str>) -> Vec<(&SpecEdgeData, &str, &str)> {
   276→        self.graph
   277→            .edge_indices()
   278→            .filter_map(|eidx| {
   279→                let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
   280→                let edge_data = &self.graph[eidx];
   281→                let src_data = &self.graph[src_idx];
   282→                let tgt_data = &self.graph[tgt_idx];
   283→                if let Some(nid) = node_id {
   284→                    if src_data.id != nid && tgt_data.id != nid {
   285→                        return None;
   286→                    }
   287→                }
   288→                Some((edge_data, src_data.id.as_str(), tgt_data.id.as_str()))
   289→            })
   290→            .collect()
   291→    }
   292→
   293→    pub fn find_edge(
   294→        &self,
   295→        source_id: &str,
   296→        target_id: &str,
   297→        kind: Option<EdgeKind>,
   298→    ) -> Option<&SpecEdgeData> {
   299→        let src_idx = self.id_to_index.get(source_id)?;
   300→        let tgt_idx = self.id_to_index.get(target_id)?;
   301→
   302→        self.graph
   303→            .edges_connecting(*src_idx, *tgt_idx)
   304→            .find(|e| kind.is_none() || Some(self.graph[e.id()].kind) == kind)
   305→            .map(|e| &self.graph[e.id()])
   306→    }
