   308→    pub fn node_count(&self) -> usize {
   309→        self.graph.node_count()
   310→    }
   311→
   312→    pub fn edge_count(&self) -> usize {
   313→        self.graph.edge_count()
   314→    }
   315→
   316→    /// Iterator over all nodes (for serialization)
   317→    pub fn nodes(&self) -> impl Iterator<Item = &SpecNodeData> {
   318→        self.graph.node_weights()
   319→    }
   320→
   321→    /// Iterator over all edges with source/target IDs (for serialization)
   322→    pub fn edges(&self) -> impl Iterator<Item = Edge> + '_ {
   323→        self.graph.edge_indices().filter_map(move |eidx| {
   324→            let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
   325→            let edge_data = self.graph[eidx].clone();
   326→            let source = self.graph[src_idx].id.clone();
   327→            let target = self.graph[tgt_idx].id.clone();
   328→            Some(Edge {
   329→                source,
   330→                target,
   331→                data: edge_data,
   332→            })
   333→        })
   334→    }
