   336→    // ========================================================================
   337→    // Search and filtering
   338→    // ========================================================================
   339→
   340→    /// Search nodes by content substring (case-insensitive).
   341→    pub fn search(&self, query: &str) -> Vec<&SpecNodeData> {
   342→        let q = query.to_lowercase();
   343→        self.graph
   344→            .node_weights()
   345→            .filter(|n| n.content.to_lowercase().contains(&q))
   346→            .collect()
   347→    }
   348→
   349→    /// Filter nodes by formality layer.
   350→    pub fn filter_by_layer(&self, min_layer: u8, max_layer: u8) -> Vec<&SpecNodeData> {
   351→        self.graph
   352→            .node_weights()
   353→            .filter(|n| n.formality_layer >= min_layer && n.formality_layer <= max_layer)
   354→            .collect()
   355→    }
   356→
   357→    // ========================================================================
   358→    // Relationship traversal
   359→    // ========================================================================
   360→
   361→    /// Trace all relationships for a node, returning a hierarchical structure.
   362→    /// Returns tuples of (node, edge_kind, direction) where direction is "outgoing" or "incoming".
   363→    pub fn trace_relationships(
   364→        &self,
   365→        node_id: &str,
   366→        max_depth: usize,
   367→    ) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
   368→        let mut result = Vec::new();
   369→        let mut visited = std::collections::HashSet::new();
   370→
   371→        if let Some(&start_idx) = self.id_to_index.get(node_id) {
   372→            visited.insert(start_idx);
   373→            self.trace_recursive(start_idx, max_depth, 0, &mut visited, &mut result);
   374→        }
   375→
   376→        result
   377→    }
   378→
   379→    fn trace_recursive(
   380→        &self,
   381→        idx: NodeIndex,
   382→        max_depth: usize,
   383→        current_depth: usize,
   384→        visited: &mut std::collections::HashSet<NodeIndex>,
   385→        result: &mut Vec<(SpecNodeData, EdgeKind, String, usize)>,
   386→    ) {
   387→        if max_depth > 0 && current_depth >= max_depth {
   388→            return;
   389→        }
   390→
   391→        // Traverse outgoing edges
   392→        for edge in self.graph.edges_directed(idx, Direction::Outgoing) {
   393→            let target_idx = edge.target();
   394→            let edge_data = &self.graph[edge.id()];
   395→            let target_node = &self.graph[target_idx];
   396→
   397→            result.push((
   398→                target_node.clone(),
   399→                edge_data.kind,
   400→                "outgoing".to_string(),
   401→                current_depth + 1,
   402→            ));
   403→
   404→            if !visited.contains(&target_idx) {
   405→                visited.insert(target_idx);
   406→                self.trace_recursive(target_idx, max_depth, current_depth + 1, visited, result);
   407→            }
   408→        }
   409→
   410→        // Traverse incoming edges
   411→        for edge in self.graph.edges_directed(idx, Direction::Incoming) {
   412→            let source_idx = edge.source();
   413→            let edge_data = &self.graph[edge.id()];
   414→            let source_node = &self.graph[source_idx];
   415→
   416→            result.push((
   417→                source_node.clone(),
   418→                edge_data.kind,
   419→                "incoming".to_string(),
   420→                current_depth + 1,
   421→            ));
   422→
   423→            if !visited.contains(&source_idx) {
   424→                visited.insert(source_idx);
   425→                self.trace_recursive(source_idx, max_depth, current_depth + 1, visited, result);
   426→            }
   427→        }
   428→    }
   429→
   430→    /// Find all formalizations of a given node (nodes it formalizes to).
   431→    pub fn find_formalizations(&self, node_id: &str) -> Vec<&SpecNodeData> {
   432→        if let Some(&idx) = self.id_to_index.get(node_id) {
   433→            self.graph
   434→                .edges_directed(idx, Direction::Outgoing)
   435→                .filter(|e| self.graph[e.id()].kind == EdgeKind::Formalizes)
   436→                .map(|e| &self.graph[e.target()])
   437→                .collect()
   438→        } else {
   439→            Vec::new()
   440→        }
   441→    }
   442→
   443→    /// Find the natural language source for a formalized node (reverse of formalizations).
   444→    pub fn find_natural_source(&self, node_id: &str) -> Vec<&SpecNodeData> {
   445→        if let Some(&idx) = self.id_to_index.get(node_id) {
   446→            self.graph
   447→                .edges_directed(idx, Direction::Incoming)
   448→                .filter(|e| self.graph[e.id()].kind == EdgeKind::Formalizes)
   449→                .map(|e| &self.graph[e.source()])
   450→                .collect()
   451→        } else {
   452→            Vec::new()
   453→        }
   454→    }
