   460→    /// Find all synonym groups: nodes connected by Synonym edges.
   461→    pub fn resolve_term(&self, term: &str) -> (Vec<&SpecNodeData>, Vec<String>) {
   462→        let t = term.to_lowercase();
   463→
   464→        // Find definition nodes matching the term
   465→        let definitions: Vec<&SpecNodeData> = self
   466→            .graph
   467→            .node_weights()
   468→            .filter(|n| n.kind == NodeKind::Definition && n.content.to_lowercase().contains(&t))
   469→            .collect();
   470→
   471→        // Collect synonyms via Synonym edges
   472→        let mut synonyms = Vec::new();
   473→        for def in &definitions {
   474→            if let Some(&idx) = self.id_to_index.get(&def.id) {
   475→                for edge in self
   476→                    .graph
   477→                    .edges_directed(idx, Direction::Outgoing)
   478→                    .chain(self.graph.edges_directed(idx, Direction::Incoming))
   479→                {
   480→                    if self.graph[edge.id()].kind == EdgeKind::Synonym {
   481→                        let other_idx = if edge.source() == idx {
   482→                            edge.target()
   483→                        } else {
   484→                            edge.source()
   485→                        };
   486→                        let other = &self.graph[other_idx];
   487→                        if !synonyms.contains(&other.content) {
   488→                            synonyms.push(other.content.clone());
   489→                        }
   490→                    }
   491→                }
   492→            }
   493→        }
   494→
   495→        (definitions, synonyms)
   496→    }
   497→
   498→    /// Find potentially related terms based on co-occurrence in metadata or content.
   499→    /// This provides a lightweight semantic clustering without requiring external AI.
   500→    pub fn find_related_terms(&self, term: &str) -> Vec<(&SpecNodeData, f32)> {
   501→        let t = term.to_lowercase();
   502→        let mut scored_nodes: Vec<(&SpecNodeData, f32)> = Vec::new();
   503→
   504→        // Find nodes that mention the term
   505→        let mentioning_nodes: Vec<&SpecNodeData> = self
   506→            .graph
   507→            .node_weights()
   508→            .filter(|n| n.content.to_lowercase().contains(&t))
   509→            .collect();
   510→
   511→        if mentioning_nodes.is_empty() {
   512→            return scored_nodes;
   513→        }
   514→
   515→        // Extract significant words from mentioning nodes (excluding common words)
   516→        let stop_words = [
   517→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
   518→        ];
   519→        let mut term_context: std::collections::HashSet<String> =
   520→            std::collections::HashSet::new();
   521→
   522→        for node in &mentioning_nodes {
   523→            for word in node.content.to_lowercase().split_whitespace() {
   524→                let clean_word = word.trim_matches(|c: char| !c.is_alphanumeric());
   525→                if clean_word.len() > 2 && !stop_words.contains(&clean_word) {
   526→                    term_context.insert(clean_word.to_string());
   527→                }
   528→            }
   529→        }
   530→
   531→        // Score all nodes based on context overlap
   532→        for node in self.graph.node_weights() {
   533→            if mentioning_nodes.contains(&node) {
   534→                continue; // Skip nodes that directly mention the term
   535→            }
   536→
   537→            let node_words: std::collections::HashSet<String> = node
   538→                .content
   539→                .to_lowercase()
   540→                .split_whitespace()
   541→                .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()).to_string())
   542→                .filter(|w| w.len() > 2 && !stop_words.contains(&w.as_str()))
   543→                .collect();
   544→
   545→            let overlap = term_context.intersection(&node_words).count();
   546→            if overlap > 0 {
   547→                let score = overlap as f32 / term_context.len().max(1) as f32;
   548→                scored_nodes.push((node, score));
   549→            }
   550→        }
   551→
   552→        // Sort by score descending
   553→        scored_nodes.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
   554→        scored_nodes
   555→    }
   556→
   557→    /// Detect potential synonym pairs based on graph structure.
   558→    /// Nodes that share similar connections might be semantically related.
   559→    pub fn detect_potential_synonyms(&self) -> Vec<(SpecNodeData, SpecNodeData, f32)> {
   560→        let mut candidates = Vec::new();
   561→        let definition_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
   562→            .graph
   563→            .node_indices()
   564→            .map(|idx| (idx, &self.graph[idx]))
   565→            .filter(|(_, n)| n.kind == NodeKind::Definition)
   566→            .collect();
   567→
   568→        for i in 0..definition_nodes.len() {
   569→            for j in (i + 1)..definition_nodes.len() {
   570→                let (idx_a, node_a) = definition_nodes[i];
   571→                let (idx_b, node_b) = definition_nodes[j];
   572→
   573→                // Skip if already marked as synonyms
   574→                let already_synonyms = self
   575→                    .graph
   576→                    .edges_directed(idx_a, Direction::Outgoing)
   577→                    .chain(self.graph.edges_directed(idx_a, Direction::Incoming))
   578→                    .any(|e| {
   579→                        self.graph[e.id()].kind == EdgeKind::Synonym
   580→                            && (e.source() == idx_b || e.target() == idx_b)
   581→                    });
   582→
   583→                if already_synonyms {
   584→                    continue;
   585→                }
   586→
   587→                // Calculate structural similarity (Jaccard similarity of neighbors)
   588→                let neighbors_a: std::collections::HashSet<NodeIndex> =
   589→                    self.graph.neighbors_undirected(idx_a).collect();
   590→                let neighbors_b: std::collections::HashSet<NodeIndex> =
   591→                    self.graph.neighbors_undirected(idx_b).collect();
   592→
   593→                if neighbors_a.is_empty() && neighbors_b.is_empty() {
   594→                    continue;
   595→                }
   596→
   597→                let intersection = neighbors_a.intersection(&neighbors_b).count();
   598→                let union = neighbors_a.union(&neighbors_b).count();
   599→
   600→                if union > 0 {
   601→                    let similarity = intersection as f32 / union as f32;
   602→                    if similarity > 0.3 {
   603→                        // Threshold for potential synonyms
   604→                        candidates.push((node_a.clone(), node_b.clone(), similarity));
   605→                    }
   606→                }
   607→            }
   608→        }
   609→
   610→        candidates.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
   611→        candidates
   612→    }
