   748→    /// Calculate compliance score between a specification and code snippet.
   749→    /// Returns score 0.0-1.0 based on semantic similarity.
   750→    pub fn calculate_compliance(&self, node_id: &str, code: &str) -> Option<ComplianceScore> {
   751→        let node = self.get_node(node_id)?;
   752→
   753→        // Extract keywords from specification
   754→        let spec_keywords = self.extract_keywords(&node.content);
   755→        let code_keywords = self.extract_keywords(code);
   756→
   757→        if spec_keywords.is_empty() {
   758→            return Some(ComplianceScore {
   759→                score: 0.0,
   760→                keyword_overlap: 0.0,
   761→                structural_match: 0.0,
   762→                explanation: "Specification has no extractable keywords".to_string(),
   763→            });
   764→        }
   765→
   766→        // Calculate keyword overlap (Jaccard similarity)
   767→        let intersection = spec_keywords.intersection(&code_keywords).count();
   768→        let union = spec_keywords.union(&code_keywords).count();
   769→        let keyword_overlap = if union > 0 {
   770→            intersection as f32 / union as f32
   771→        } else {
   772→            0.0
   773→        };
   774→
   775→        // Structural matching for constraints/scenarios
   776→        let structural_match = match node.kind {
   777→            NodeKind::Constraint => self.match_constraint_structure(&node.content, code),
   778→            NodeKind::Scenario => self.match_scenario_structure(&node.content, code),
   779→            _ => 0.5, // Neutral for other types
   780→        };
   781→
   782→        // Weighted average (60% keywords, 40% structure)
   783→        let score = keyword_overlap * 0.6 + structural_match * 0.4;
   784→
   785→        let explanation = if score > 0.8 {
   786→            "Strong compliance - code closely matches specification".to_string()
   787→        } else if score > 0.5 {
   788→            "Moderate compliance - code partially matches specification".to_string()
   789→        } else if score > 0.2 {
   790→            "Weak compliance - code loosely relates to specification".to_string()
   791→        } else {
   792→            "Poor compliance - code does not match specification".to_string()
   793→        };
   794→
   795→        Some(ComplianceScore {
   796→            score,
   797→            keyword_overlap,
   798→            structural_match,
   799→            explanation,
   800→        })
   801→    }
   802→
   803→    fn extract_keywords(&self, text: &str) -> std::collections::HashSet<String> {
   804→        let stop_words = [
   805→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "is", "are",
   806→            "was", "were", "be", "been", "being", "have", "has", "had", "do", "does", "did",
   807→            "will", "would", "should", "could", "may", "might", "must", "can", "of", "by",
   808→            "with", "from", "as", "into", "through",
   809→        ];
   810→
   811→        text.to_lowercase()
   812→            .split_whitespace()
   813→            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()))
   814→            .filter(|w| w.len() > 2 && !stop_words.contains(w))
   815→            .map(|w| w.to_string())
   816→            .collect()
   817→    }
   818→
   819→    fn match_constraint_structure(&self, spec: &str, code: &str) -> f32 {
   820→        let spec_lower = spec.to_lowercase();
   821→        let code_lower = code.to_lowercase();
   822→
   823→        let mut score: f32 = 0.0;
   824→
   825→        // Look for constraint patterns
   826→        if (spec_lower.contains("must") || spec_lower.contains("should"))
   827→            && (code_lower.contains("assert")
   828→                || code_lower.contains("require")
   829→                || code_lower.contains("invariant"))
   830→        {
   831→            score += 0.3;
   832→        }
   833→
   834→        // Look for comparison operators
   835→        if (spec_lower.contains('>')
   836→            || spec_lower.contains('<')
   837→            || spec_lower.contains("greater")
   838→            || spec_lower.contains("less"))
   839→            && (code_lower.contains('>') || code_lower.contains('<'))
   840→        {
   841→            score += 0.2;
   842→        }
   843→
   844→        // Look for equality checks
   845→        if (spec_lower.contains("equal") || spec_lower.contains("same"))
   846→            && (code_lower.contains("==") || code_lower.contains("equals"))
   847→        {
   848→            score += 0.2;
   849→        }
   850→
   851→        // Look for boundary conditions
   852→        if (spec_lower.contains("not") || spec_lower.contains("never"))
   853→            && (code_lower.contains('!') || code_lower.contains("not"))
   854→        {
   855→            score += 0.3;
   856→        }
   857→
   858→        score.min(1.0)
   859→    }
   860→
   861→    fn match_scenario_structure(&self, spec: &str, code: &str) -> f32 {
   862→        let spec_lower = spec.to_lowercase();
   863→        let code_lower = code.to_lowercase();
   864→
   865→        let mut score: f32 = 0.0;
   866→
   867→        // Look for action words
   868→        let action_words = [
   869→            "login", "create", "update", "delete", "send", "receive", "verify",
   870→        ];
   871→        let has_action = action_words
   872→            .iter()
   873→            .any(|&w| spec_lower.contains(w) && code_lower.contains(w));
   874→        if has_action {
   875→            score += 0.4;
   876→        }
   877→
   878→        // Look for test structure
   879→        if code_lower.contains("test") || code_lower.contains("scenario") {
   880→            score += 0.2;
   881→        }
   882→
   883→        // Look for setup/action/verify pattern
   884→        let has_setup = code_lower.contains("setup") || code_lower.contains("given");
   885→        let has_action_code = code_lower.contains("when") || code_lower.contains("act");
   886→        let has_verify = code_lower.contains("assert")
   887→            || code_lower.contains("verify")
   888→            || code_lower.contains("expect");
   889→
   890→        if has_setup {
   891→            score += 0.1;
   892→        }
   893→        if has_action_code {
   894→            score += 0.15;
   895→        }
   896→        if has_verify {
   897→            score += 0.15;
   898→        }
   899→
   900→        score.min(1.0)
   901→    }
