   903→    /// Get compliance report for all specifications with linked code.
   904→    pub fn get_compliance_report(&self) -> Vec<(SpecNodeData, ComplianceScore)> {
   905→        self.graph
   906→            .node_weights()
   907→            .filter(|n| n.metadata.contains_key("impl_code") || n.metadata.contains_key("test_code"))
   908→            .filter_map(|n| {
   909→                let code = n
   910→                    .metadata
   911→                    .get("impl_code")
   912→                    .or_else(|| n.metadata.get("test_code"))?;
   913→                let score = self.calculate_compliance(&n.id, code)?;
   914→                Some((n.clone(), score))
   915→            })
   916→            .collect()
   917→    }
