   923→    /// Query graph state at a specific timestamp.
   924→    /// Returns nodes and edges that existed at that time.
   925→    pub fn query_at_timestamp(&self, timestamp: i64) -> TemporalSnapshot {
   926→        let nodes: Vec<SpecNodeData> = self
   927→            .graph
   928→            .node_weights()
   929→            .filter(|n| n.created_at <= timestamp)
   930→            .cloned()
   931→            .collect();
   932→
   933→        let edges: Vec<SpecEdgeData> = self
   934→            .graph
   935→            .edge_indices()
   936→            .filter_map(|eidx| {
   937→                let edge = &self.graph[eidx];
   938→                if edge.created_at <= timestamp {
   939→                    Some(edge.clone())
   940→                } else {
   941→                    None
   942→                }
   943→            })
   944→            .collect();
   945→
   946→        let node_count = nodes.len();
   947→        let edge_count = edges.len();
   948→
   949→        TemporalSnapshot {
   950→            timestamp,
   951→            nodes,
   952→            edges,
   953→            node_count,
   954→            edge_count,
   955→        }
   956→    }
