   958→    /// Diff graph state between two timestamps.
   959→    /// Shows what was added, modified, or removed.
   960→    pub fn diff_timestamps(&self, from_timestamp: i64, to_timestamp: i64) -> TemporalDiff {
   961→        let from_snapshot = self.query_at_timestamp(from_timestamp);
   962→        let to_snapshot = self.query_at_timestamp(to_timestamp);
   963→
   964→        let from_node_ids: std::collections::HashSet<String> =
   965→            from_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   966→        let to_node_ids: std::collections::HashSet<String> =
   967→            to_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   968→
   969→        let added_nodes: Vec<SpecNodeData> = to_snapshot
   970→            .nodes
   971→            .iter()
   972→            .filter(|n| !from_node_ids.contains(&n.id))
   973→            .cloned()
   974→            .collect();
   975→
   976→        let removed_nodes: Vec<SpecNodeData> = from_snapshot
   977→            .nodes
   978→            .iter()
   979→            .filter(|n| !to_node_ids.contains(&n.id))
   980→            .cloned()
   981→            .collect();
   982→
   983→        let modified_nodes: Vec<(SpecNodeData, SpecNodeData)> = to_snapshot
   984→            .nodes
   985→            .iter()
   986→            .filter_map(|to_node| {
   987→                from_snapshot
   988→                    .nodes
   989→                    .iter()
   990→                    .find(|from_node| from_node.id == to_node.id)
   991→                    .and_then(|from_node| {
   992→                        if from_node.modified_at < to_node.modified_at {
   993→                            Some((from_node.clone(), to_node.clone()))
   994→                        } else {
   995→                            None
   996→                        }
   997→                    })
   998→            })
   999→            .collect();
  1000→
  1001→        let from_edge_ids: std::collections::HashSet<String> =
  1002→            from_snapshot.edges.iter().map(|e| e.id.clone()).collect();
  1003→        let to_edge_ids: std::collections::HashSet<String> =
  1004→            to_snapshot.edges.iter().map(|e| e.id.clone()).collect();
  1005→
  1006→        let added_edges: Vec<SpecEdgeData> = to_snapshot
  1007→            .edges
  1008→            .iter()
  1009→            .filter(|e| !from_edge_ids.contains(&e.id))
  1010→            .cloned()
  1011→            .collect();
  1012→
  1013→        let removed_edges: Vec<SpecEdgeData> = from_snapshot
  1014→            .edges
  1015→            .iter()
  1016→            .filter(|e| !to_edge_ids.contains(&e.id))
  1017→            .cloned()
  1018→            .collect();
  1019→
  1020→        TemporalDiff {
  1021→            from_timestamp,
  1022→            to_timestamp,
  1023→            added_nodes,
  1024→            removed_nodes,
  1025→            modified_nodes,
  1026→            added_edges,
  1027→            removed_edges,
  1028→        }
  1029→    }
