  1031→    /// Get evolution history of a specific node.
  1032→    /// Returns timeline of changes to the node.
  1033→    pub fn get_node_history(&self, node_id: &str) -> Option<NodeHistory> {
  1034→        let node = self.get_node(node_id)?;
  1035→
  1036→        let mut events = Vec::new();
  1037→
  1038→        // Creation event
