/// Convert from legacy SpecGraph to SpecRepository
pub fn from_spec_graph(spec_graph: &crate::SpecGraph) -> Self {
    let mut repo = Self::new();

    // Add all nodes - convert from graph::SpecNodeData to data::SpecNodeData
    for node in spec_graph.list_nodes(None) {
        let data_node = SpecNodeData {
            id: node.id.clone(),
            content: node.content.clone(),
            kind: match node.kind {
                crate::NodeKind::Assertion => NodeKind::Assertion,
                crate::NodeKind::Constraint => NodeKind::Constraint,
                crate::NodeKind::Scenario => NodeKind::Scenario,
                crate::NodeKind::Definition => NodeKind::Definition,
                crate::NodeKind::Domain => NodeKind::Domain,
            },
            metadata: node.metadata.clone(),
            created_at: node.created_at,
            modified_at: node.modified_at,
            formality_layer: node.formality_layer,
        };
        repo.add_node_from_loaded(data_node);
    }

    // Add all edges - convert from graph::EdgeKind to data::EdgeKind
    for (edge_data, source_id, target_id) in spec_graph.list_edges(None) {
        let kind = match edge_data.kind {
            crate::EdgeKind::Formalizes => EdgeKind::Formalizes,
            crate::EdgeKind::Transform => EdgeKind::Transform,
            crate::EdgeKind::Refines => EdgeKind::Refines,
            crate::EdgeKind::DerivesFrom => EdgeKind::DerivesFrom,
