            crate::EdgeKind::Contradicts => EdgeKind::Contradicts,
            crate::EdgeKind::Synonym => EdgeKind::Synonym,
            crate::EdgeKind::Composes => EdgeKind::Composes,
        };
        // Add edge using source and target IDs
        let _ = repo.add_edge(source_id, target_id, kind, edge_data.metadata.clone());
    }

    repo
