     1→/// AI-powered semantic analysis for cross-layer specification matching
     2→///
     3→/// This module uses AI to understand semantic equivalence between specifications
     4→/// at different formality layers, enabling the tool to recognize that:
     5→/// - "Password must be >= 8 chars" (natural language)
     6→/// - `assert!(password.len() >= 8)` (executable code)
     7→/// are the same specification.
     8→
     9→use std::collections::HashMap;
    10→use std::process::{Command, Stdio};
    11→use std::sync::{Arc, Mutex};
    12→
    13→/// Cache for AI semantic similarity results to avoid redundant calls
    14→type SimilarityCache = Arc<Mutex<HashMap<(String, String), f32>>>;
    15→
    16→pub struct AISemantic {
    17→    cache: SimilarityCache,
    18→    ai_command: String,
    19→}
    20→
    21→impl Default for AISemantic {
    22→    fn default() -> Self {
    23→        Self::new("claude")
    24→    }
    25→}
    26→
    27→impl AISemantic {
    28→    pub fn new(ai_command: &str) -> Self {
    29→        Self {
    30→            cache: Arc::new(Mutex::new(HashMap::new())),
    31→            ai_command: ai_command.to_string(),
    32→        }
    33→    }
    34→
    35→    /// Check if AI command is available
    36→    pub fn is_available(&self) -> bool {
    37→        Command::new(&self.ai_command)
    38→            .arg("--version")
    39→            .stdout(Stdio::null())
    40→            .stderr(Stdio::null())
    41→            .status()
    42→            .is_ok()
    43→    }
    44→
    45→    /// Calculate semantic similarity using AI (0.0 to 1.0)
    46→    ///
    47→    /// This is expensive, so use sparingly:
    48→    /// - Only for cross-layer comparisons where simple similarity fails
    49→    /// - Cache results aggressively
    50→    /// - Batch requests when possible
    51→    pub fn semantic_similarity(&self, spec1: &str, spec2: &str, layer1: u8, layer2: u8) -> Option<f32> {
    52→        // Check cache first
    53→        let cache_key = self.make_cache_key(spec1, spec2);
    54→        if let Ok(cache) = self.cache.lock()
    55→            && let Some(&score) = cache.get(&cache_key) {
    56→                return Some(score);
    57→            }
    58→
    59→        // Call AI if available
    60→        if !self.is_available() {
    61→            return None;
    62→        }
    63→
    64→        let prompt = format!(
    65→            r#"Compare these two specifications and return ONLY a number from 0.0 to 1.0 representing semantic similarity:
    66→
    67→Spec A (formality layer {}): {}
    68→
    69→Spec B (formality layer {}): {}
    70→
    71→Consider:
    72→- Do they specify the same requirement/constraint/behavior?
    73→- Ignore syntactic differences (natural language vs code)
    74→- Focus on semantic equivalence
    75→
    76→Return only the similarity score (e.g., 0.85), no explanation.
    77→Formality layers: 0=natural language, 1=structured, 2=formal, 3=executable code."#,
    78→            layer1, spec1, layer2, spec2
    79→        );
    80→
    81→        let output = Command::new(&self.ai_command)
    82→            .arg("-p")
    83→            .arg(&prompt)
    84→            .output()
    85→            .ok()?;
    86→
    87→        if !output.status.success() {
    88→            return None;
    89→        }
    90→
    91→        let response = String::from_utf8(output.stdout).ok()?;
    92→        let score = response.trim().parse::<f32>().ok()?;
    93→
    94→        // Clamp to valid range
    95→        let score = score.max(0.0).min(1.0);
    96→
    97→        // Cache result
    98→        if let Ok(mut cache) = self.cache.lock() {
    99→            cache.insert(cache_key, score);
   100→        }
   101→
   102→        Some(score)
   103→    }
   104→
   105→    /// Batch semantic similarity for multiple pairs (more efficient)
   106→    pub fn batch_semantic_similarity(
   107→        &self,
   108→        pairs: Vec<(&str, u8, &str, u8)>,
   109→    ) -> Vec<Option<f32>> {
   110→        pairs
   111→            .iter()
   112→            .map(|(s1, l1, s2, l2)| self.semantic_similarity(s1, s2, *l1, *l2))
   113→            .collect()
   114→    }
   115→
   116→    /// Normalize specification text for caching
   117→    fn normalize_for_cache(&self, text: &str) -> String {
   118→        // Normalize whitespace and case for consistent caching
   119→        text.split_whitespace()
   120→            .collect::<Vec<_>>()
   121→            .join(" ")
   122→            .to_lowercase()
   123→    }
   124→
   125→    /// Create cache key (order-independent)
   126→    fn make_cache_key(&self, spec1: &str, spec2: &str) -> (String, String) {
   127→        let norm1 = self.normalize_for_cache(spec1);
   128→        let norm2 = self.normalize_for_cache(spec2);
   129→
   130→        // Order-independent key
   131→        if norm1 < norm2 {
   132→            (norm1, norm2)
   133→        } else {
   134→            (norm2, norm1)
   135→        }
   136→    }
   137→
   138→    /// Clear the similarity cache
   139→    pub fn clear_cache(&self) {
   140→        if let Ok(mut cache) = self.cache.lock() {
   141→            cache.clear();
   142→        }
   143→    }
   144→
   145→    /// Get cache statistics
   146→    pub fn cache_stats(&self) -> (usize, usize) {
   147→        if let Ok(cache) = self.cache.lock() {
   148→            let size = cache.len();
   149→            let capacity = cache.capacity();
   150→            (size, capacity)
   151→        } else {
   152→            (0, 0)
   153→        }
   154→    }
   155→}
