     1→/// AI-powered semantic analysis for cross-layer specification matching
     2→///
     3→/// This module uses AI to understand semantic equivalence between specifications
     4→/// at different formality layers, enabling the tool to recognize that:
     5→/// - "Password must be >= 8 chars" (natural language)
     6→/// - `assert!(password.len() >= 8)` (executable code)
     7→/// are the same specification.
     8→use std::collections::HashMap;
     9→use std::process::{Command, Stdio};
    10→use std::sync::{Arc, Mutex};
    11→
    12→/// Cache for AI semantic similarity results to avoid redundant calls
    13→type SimilarityCache = Arc<Mutex<HashMap<(String, String), f32>>>;
    14→
    15→pub struct AISemantic {
    16→    cache: SimilarityCache,
    17→    ai_command: String,
    18→}
    19→
    20→impl Default for AISemantic {
    21→    fn default() -> Self {
    22→        Self::new("claude")
    23→    }
    24→}
    25→
    26→impl AISemantic {
    27→    pub fn new(ai_command: &str) -> Self {
    28→        Self {
    29→            cache: Arc::new(Mutex::new(HashMap::new())),
    30→            ai_command: ai_command.to_string(),
    31→        }
    32→    }
    33→
    34→    /// Check if AI command is available
    35→    pub fn is_available(&self) -> bool {
    36→        Command::new(&self.ai_command)
    37→            .arg("--version")
    38→            .stdout(Stdio::null())
    39→            .stderr(Stdio::null())
    40→            .status()
    41→            .is_ok()
    42→    }
    43→
    44→    /// Calculate semantic similarity using AI (0.0 to 1.0)
    45→    ///
    46→    /// This is expensive, so use sparingly:
    47→    /// - Only for cross-layer comparisons where simple similarity fails
    48→    /// - Cache results aggressively
    49→    /// - Batch requests when possible
    50→    pub fn semantic_similarity(&self, spec1: &str, spec2: &str, layer1: u8, layer2: u8) -> Option<f32> {
    51→        // Check cache first
    52→        let cache_key = self.make_cache_key(spec1, spec2);
    53→        if let Ok(cache) = self.cache.lock()
    54→            && let Some(&score) = cache.get(&cache_key) {
    55→                return Some(score);
    56→            }
    57→
    58→        // Call AI if available
    59→        if !self.is_available() {
    60→            return None;
    61→        }
    62→
    63→        let prompt = format!(
    64→            r#"Compare these two specifications and return ONLY a number from 0.0 to 1.0 representing semantic similarity:
    65→
    66→Spec A (formality layer {}): {}
    67→
    68→Spec B (formality layer {}): {}
    69→
    70→Consider:
    71→- Do they specify the same requirement/constraint/behavior?
    72→- Ignore syntactic differences (natural language vs code)
    73→- Focus on semantic equivalence
    74→
    75→Return only the similarity score (e.g., 0.85), no explanation.
    76→Formality layers: 0=natural language, 1=structured, 2=formal, 3=executable code."#,
    77→            layer1, spec1, layer2, spec2
    78→        );
    79→
    80→        let output = Command::new(&self.ai_command)
    81→            .arg("-p")
    82→            .arg(&prompt)
    83→            .output()
    84→            .ok()?;
    85→
    86→        if !output.status.success() {
    87→            return None;
    88→        }
    89→
    90→        let response = String::from_utf8(output.stdout).ok()?;
    91→        let score = response.trim().parse::<f32>().ok()?;
    92→
    93→        // Clamp to valid range
    94→        let score = score.max(0.0).min(1.0);
    95→
    96→        // Cache result
    97→        if let Ok(mut cache) = self.cache.lock() {
    98→            cache.insert(cache_key, score);
    99→        }
