   313→    /// Trace all relationships for a node, returning a hierarchical structure.
   314→    /// Returns tuples of (node, edge_kind, direction) where direction is "outgoing" or "incoming".
   315→    pub fn trace_relationships(
   316→        &self,
   317→        node_id: &str,
   318→        max_depth: usize,
   319→    ) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
   320→        let mut result = Vec::new();
   321→        let mut visited = std::collections::HashSet::new();
   322→
   323→        if let Some(&start_idx) = self.id_to_index.get(node_id) {
   324→            visited.insert(start_idx);
   325→            self.trace_recursive(start_idx, max_depth, 0, &mut visited, &mut result);
   326→        }
   327→
   328→        result
   329→    }
   330→
   331→    fn trace_recursive(
   332→        &self,
   333→        idx: NodeIndex,
   334→        max_depth: usize,
   335→        current_depth: usize,
   336→        visited: &mut std::collections::HashSet<NodeIndex>,
   337→        result: &mut Vec<(SpecNodeData, EdgeKind, String, usize)>,
   338→    ) {
   339→        if max_depth > 0 && current_depth >= max_depth {
   340→            return;
   341→        }
   342→
   343→        // Traverse outgoing edges
   344→        for edge in self.graph.edges_directed(idx, Direction::Outgoing) {
   345→            let target_idx = edge.target();
   346→            let edge_data = &self.graph[edge.id()];
   347→            let target_node = &self.graph[target_idx];
   348→
   349→            result.push((
   350→                target_node.clone(),
   351→                edge_data.kind,
   352→                "outgoing".to_string(),
   353→                current_depth + 1,
   354→            ));
   355→
   356→            if !visited.contains(&target_idx) {
   357→                visited.insert(target_idx);
   358→                self.trace_recursive(target_idx, max_depth, current_depth + 1, visited, result);
   359→            }
   360→        }
   361→
   362→        // Traverse incoming edges
   363→        for edge in self.graph.edges_directed(idx, Direction::Incoming) {
   364→            let source_idx = edge.source();
   365→            let edge_data = &self.graph[edge.id()];
   366→            let source_node = &self.graph[source_idx];
   367→
   368→            result.push((
   369→                source_node.clone(),
   370→                edge_data.kind,
   371→                "incoming".to_string(),
   372→                current_depth + 1,
   373→            ));
   374→
   375→            if !visited.contains(&source_idx) {
   376→                visited.insert(source_idx);
   377→                self.trace_recursive(source_idx, max_depth, current_depth + 1, visited, result);
   378→            }
   379→        }
   380→    }
