   700→    /// Calculate compliance score between a specification and code snippet.
   701→    /// Returns score 0.0-1.0 based on semantic similarity.
   702→    pub fn calculate_compliance(&self, node_id: &str, code: &str) -> Option<ComplianceScore> {
   703→        let node = self.get_node(node_id)?;
   704→
   705→        // Extract keywords from specification
   706→        let spec_keywords = self.extract_keywords(&node.content);
   707→        let code_keywords = self.extract_keywords(code);
   708→
   709→        if spec_keywords.is_empty() {
   710→            return Some(ComplianceScore {
   711→                score: 0.0,
   712→                keyword_overlap: 0.0,
   713→                structural_match: 0.0,
   714→                explanation: "Specification has no extractable keywords".to_string(),
   715→            });
   716→        }
   717→
   718→        // Calculate keyword overlap (Jaccard similarity)
   719→        let intersection = spec_keywords.intersection(&code_keywords).count();
   720→        let union = spec_keywords.union(&code_keywords).count();
   721→        let keyword_overlap = if union > 0 {
   722→            intersection as f32 / union as f32
   723→        } else {
   724→            0.0
   725→        };
   726→
   727→        // Structural matching for constraints/scenarios
   728→        let structural_match = match node.kind {
   729→            NodeKind::Constraint => self.match_constraint_structure(&node.content, code),
   730→            NodeKind::Scenario => self.match_scenario_structure(&node.content, code),
   731→            _ => 0.5, // Neutral for other types
   732→        };
   733→
   734→        // Weighted average (60% keywords, 40% structure)
   735→        let score = keyword_overlap * 0.6 + structural_match * 0.4;
   736→
   737→        let explanation = if score > 0.8 {
   738→            "Strong compliance - code closely matches specification".to_string()
   739→        } else if score > 0.5 {
   740→            "Moderate compliance - code partially matches specification".to_string()
   741→        } else if score > 0.2 {
   742→            "Weak compliance - code loosely relates to specification".to_string()
   743→        } else {
   744→            "Poor compliance - code does not match specification".to_string()
   745→        };
   746→
   747→        Some(ComplianceScore {
   748→            score,
   749→            keyword_overlap,
   750→            structural_match,
   751→            explanation,
   752→        })
   753→    }
   754→
   755→    fn extract_keywords(&self, text: &str) -> std::collections::HashSet<String> {
   756→        let stop_words = [
   757→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "is", "are",
   758→            "was", "were", "be", "been", "being", "have", "has", "had", "do", "does", "did",
   759→            "will", "would", "should", "could", "may", "might", "must", "can", "of", "by",
   760→            "with", "from", "as", "into", "through",
   761→        ];
   762→
   763→        text.to_lowercase()
   764→            .split_whitespace()
   765→            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()))
   766→            .filter(|w| w.len() > 2 && !stop_words.contains(w))
   767→            .map(|w| w.to_string())
   768→            .collect()
   769→    }
   770→
   771→    fn match_constraint_structure(&self, spec: &str, code: &str) -> f32 {
   772→        let spec_lower = spec.to_lowercase();
   773→        let code_lower = code.to_lowercase();
   774→
   775→        let mut score: f32 = 0.0;
   776→
   777→        // Look for constraint patterns
   778→        if (spec_lower.contains("must") || spec_lower.contains("should"))
   779→            && (code_lower.contains("assert")
   780→                || code_lower.contains("require")
   781→                || code_lower.contains("invariant"))
   782→        {
   783→            score += 0.3;
   784→        }
   785→
   786→        // Look for comparison operators
   787→        if (spec_lower.contains('>')
   788→            || spec_lower.contains('<')
   789→            || spec_lower.contains("greater")
   790→            || spec_lower.contains("less"))
   791→            && (code_lower.contains('>') || code_lower.contains('<'))
   792→        {
   793→            score += 0.2;
   794→        }
   795→
   796→        // Look for equality checks
   797→        if (spec_lower.contains("equal") || spec_lower.contains("same"))
   798→            && (code_lower.contains("==") || code_lower.contains("equals"))
   799→        {
   800→            score += 0.2;
   801→        }
   802→
   803→        // Look for boundary conditions
   804→        if (spec_lower.contains("not") || spec_lower.contains("never"))
   805→            && (code_lower.contains('!') || code_lower.contains("not"))
   806→        {
   807→            score += 0.3;
   808→        }
   809→
   810→        score.min(1.0)
   811→    }
   812→
   813→    fn match_scenario_structure(&self, spec: &str, code: &str) -> f32 {
   814→        let spec_lower = spec.to_lowercase();
   815→        let code_lower = code.to_lowercase();
   816→
