    22→impl ModelSync {
    23→    /// Synchronize UDAFModel from SpecRepository
    24→    ///
    25→    /// This populates the formal model by reading nodes and edges from the repository:
    26→    /// - Universes are created based on formality_layer (0=U0, 1=U1, etc.)
    27→    /// - Domains are extracted from Domain nodes
    28→    /// - Admissible sets are created for each specification
    29→    /// - Constraints are extracted from node content
    30→    /// - Transform functions are built from edge relationships
    31→    ///
    32→    /// Returns Ok(()) on success, or Err with error message.
    33→    pub fn sync_from_repository(model: &mut UDAFModel, repo: &SpecRepository) -> Result<(), String> {
    34→        // Clear existing data
    35→        model.universes.clear();
    36→        model.domains.clear();
    37→        model.admissible_sets.clear();
    38→        model.transforms.clear();
    39→
    40→        // Always create U0 (root universe)
    41→        let u0 = Universe::root();
    42→        model.universes.insert(u0.id.clone(), u0);
    43→
    44→        // First pass: Create universes and admissible sets from nodes
    45→        Self::sync_nodes(model, repo)?;
    46→
    47→        // Second pass: Create transform functions from edges
    48→        Self::sync_edges(model, repo)?;
    49→
    50→        // Third pass: Create inverse transforms for each projection universe
    51→        Self::create_inverse_transforms(model)?;
    52→
    53→        Ok(())
    54→    }
