   168→    /// Sync nodes from repository to model
   169→    fn sync_nodes(model: &mut UDAFModel, repo: &SpecRepository) -> Result<(), String> {
   170→        for node in repo.list_nodes(None) {
   171→            let layer = node.formality_layer;
   172→
   173→            // Create universe for this layer if it doesn't exist
   174→            let universe_id = match UniverseId::parse(&format!("U{}", layer)) {
   175→                Ok(id) => id,
   176→                Err(_) => continue,
   177→            };
   178→
   179→            if !model.universes.contains_key(&universe_id) && layer > 0 {
   180→                let (name, description) = Self::universe_names_for_layer(layer);
   181→                model.add_universe(layer, name, description)
   182→                    .map_err(|e| format!("Failed to add universe: {}", e))?;
   183→            }
   184→
   185→            // Parse spec ID
   186→            let spec_id = match SpecId::parse(&node.id) {
   187→                Ok(id) => id,
   188→                Err(_) => continue,
   189→            };
   190→
   191→            // Add spec to universe
   192→            if let Some(universe) = model.universes.get_mut(&universe_id) {
   193→                universe.specifications.insert(spec_id.clone());
   194→            }
   195→
   196→            // Create admissible set for this specification
   197→            let mut admissible_set = AdmissibleSet::new(spec_id.clone(), universe_id.clone());
   198→
   199→            // Extract constraints based on node kind
   200→            match node.kind {
   201→                NodeKind::Constraint => {
   202→                    // For Constraint nodes, create a single explicit constraint
   203→                    let mut meta = ConstraintMetadata::from(node.metadata.clone());
   204→                    meta.insert(MetadataKey::Custom("description".to_string()), node.content.clone());
   205→
   206→                    admissible_set.add_constraint(Constraint {
   207→                        formal: None, // Will be extracted during proof preparation
   208→                        kind: ConstraintKind::Universal,
   209→                        description: Some(node.content.clone()),
   210→                        metadata: Some(ConstraintMetadata::from(node.metadata.clone())),
   211→                        meta: Some(meta),
   212→                    });
   213→                }
   214→                _ => {
   215→                    // For other nodes, extract implicit constraints from natural language
   216→                    let extracted = extract_constraints_from_text(&node.content);
   217→                    for constraint in extracted {
   218→                        admissible_set.add_constraint(constraint);
   219→                    }
   220→                }
   221→            }
   222→
   223→            model.admissible_sets.insert(spec_id.clone(), admissible_set);
   224→
   225→            // Create domain if this is a Domain node
   226→            if node.kind == NodeKind::Domain {
   227→                let domain = Domain::with_id(
   228→                    DomainId::parse(&node.id).unwrap_or_else(|_| DomainId::new()),
   229→                    node.content.clone(),
   230→                    "Domain boundary definition".to_string(),
   231→                    universe_id,
   232→                );
   233→                model.domains.insert(domain.id.clone(), domain);
   234→            }
   235→        }
   236→
   237→        Ok(())
   238→    }
   239→
   240→    /// Sync edges from repository to model
   241→    fn sync_edges(model: &mut UDAFModel, repo: &SpecRepository) -> Result<(), String> {
   242→        for (edge, source_id, target_id) in repo.list_edges(None) {
   243→            // Only process Formalizes and Transform edges
   244→            if !matches!(edge.kind, EdgeKind::Formalizes | EdgeKind::Transform) {
   245→                continue;
   246→            }
   247→
   248→            let source_node = match repo.get_node(source_id) {
   249→                Some(n) => n,
   250→                None => continue,
   251→            };
   252→
   253→            let target_node = match repo.get_node(target_id) {
   254→                Some(n) => n,
   255→                None => continue,
   256→            };
   257→
   258→            // Parse universe IDs
   259→            let source_universe = match UniverseId::parse(&format!("U{}", source_node.formality_layer)) {
   260→                Ok(id) => id,
   261→                Err(_) => continue,
   262→            };
   263→
   264→            let target_universe = match UniverseId::parse(&format!("U{}", target_node.formality_layer)) {
   265→                Ok(id) => id,
   266→                Err(_) => continue,
   267→            };
   268→
   269→            // Create transform function
   270→            let transform = TransformFunction::forward(
   271→                source_universe,
   272→                target_universe,
   273→                format!(
   274→                    "{:?}: {} -> {}",
   275→                    edge.kind,
   276→                    source_node.content.chars().take(30).collect::<String>(),
   277→                    target_node.content.chars().take(30).collect::<String>()
   278→                ),
   279→                TransformStrategy::Manual {
   280→                    description: format!("Manual transformation via {:?} edge", edge.kind),
   281→                },
   282→            );
   283→
   284→            model.transforms.insert(transform.id.clone(), transform);
   285→        }
   286→
   287→        Ok(())
   288→    }
   289→
   290→    /// Create inverse transforms for each projection universe to U0
   291→    fn create_inverse_transforms(model: &mut UDAFModel) -> Result<(), String> {
   292→        let universe_ids: Vec<UniverseId> = model.universes.keys().cloned().collect();
   293→
   294→        for universe_id in universe_ids {
   295→            if universe_id.layer() == 0 {
   296→                continue; // Skip U0 itself
   297→            }
   298→
   299→            let layer_num = universe_id.layer();
   300→
   301→            // Create inverse transform based on layer
   302→            let strategy = match layer_num {
   303→                3 => TransformStrategy::ASTAnalysis {
   304→                    language: "rust".to_string(),
   305→                    extractor_config: HashMap::from([
   306→                        ("min_confidence".to_string(), "0.7".to_string()),
   307→                    ]),
   308→                },
   309→                2 => TransformStrategy::TypeAnalysis {
   310→                    type_system: "rust".to_string(),
   311→                },
   312→                1 => TransformStrategy::FormalVerification {
   313→                    tool: "manual".to_string(),
   314→                    verification_config: HashMap::new(),
   315→                },
   316→                _ => TransformStrategy::Manual {
   317→                    description: format!("Inverse mapping from {}", universe_id.as_str()),
   318→                },
   319→            };
   320→
   321→            let transform = TransformFunction::inverse(
   322→                universe_id.clone(),
   323→                format!("Inverse mapping from {} to U0", universe_id.as_str()),
   324→                strategy,
   325→            );
   326→
   327→            model.transforms.insert(transform.id.clone(), transform);
   328→        }
   329→
   330→        Ok(())
   331→    }
   332→
   333→    /// Get standard universe names for a layer
   334→    fn universe_names_for_layer(layer: u8) -> (String, String) {
   335→        match layer {
   336→            1 => (
   337→                "Formal Specifications".to_string(),
   338→                "Structured formal specifications".to_string(),
   339→            ),
   340→            2 => (
   341→                "Interface Definitions".to_string(),
   342→                "Interface contracts and protocols".to_string(),
   343→            ),
   344→            3 => (
   345→                "Executable Implementations".to_string(),
   346→                "Actual code implementations".to_string(),
   347→            ),
   348→            _ => (
   349→                format!("Layer {}", layer),
   350→                format!("Layer {} specifications", layer),
   351→            ),
   352→        }
   353→    }
   354→}
