                    spec_a_id,
                    "proof_timestamp".to_string(),
                    timestamp.clone(),
                );

                repo.update_node_metadata(
                    spec_b_id,
                    "contradiction_detected".to_string(),
                    spec_a_id.to_string(),
                );
                repo.update_node_metadata(
                    spec_b_id,
                    "proof_timestamp".to_string(),
                    timestamp.clone(),
